\subsection{Upper bounds via the random purification channel}

Combining the random purification channel with Werner's pure state cloner straightforwardly gives a simple mixed state cloner. 

{
\floatstyle{boxed} 
\restylefloat{figure}
\begin{figure}[H]
Given $n$ copies of a rank-$r$ mixed state $\rho_{\reg{A}}$:
\begin{enumerate}
    \item Apply $\Purify^{(d,r,n)}$ to prepare $n$ copies of a random purification $\ket{\brho}_{\reg{AB}} \in \C^d \otimes \C^r$. Set $D = d \cdot r$. 
    \item Apply $\Werner^{(D, n, k)}$, yielding a mixed state $\bsigma_{\reg{AB}} \in \states( \C^d \otimes \C^r)^{\otimes (n+k)}$. 
    \item Trace out the auxiliary registers, and output $\Tr_{\reg{B}}(\bsigma_{\reg{AB}}) \in \states(\C^d)^{\otimes (n+k)}$. 
\end{enumerate}
\caption{A mixed state cloning channel, which we call the \emph{PCT cloner}, due to its action: \emph{purify--clone--trace}. We denote the PCT cloner by $\PCT^{(d,n,k)}$. As usual, we will sometimes drop the superscript's parameters when these are clear from context.}
\label{fig:reduction}
\end{figure}
}

This natural construction has already appeared in the literature, in e.g.\ \cite{LTHC26}. Here we give an analysis of its sample complexity. This result, when combined with our lower bounds, shows that the PCT cloner is sample-optimal, despite its simplicity. 

\begin{proposition}[Sample complexity of the PCT cloner] \label{prop:upper_bound_PCT}
    With $n = O(krd/\eps)$ copies of a mixed state $\rho \in \states(\C^d)$, the PCT cloner $\PCT^{(d,n,k)}$ produces an $(n+k)$-copy state with fidelity at least $1-\eps$ with $\rho^{\otimes (n+k)}$. 
\end{proposition}

\begin{proof}
    We start by writing
    \begin{equation*}
        \PCT(\rho^{\otimes n}) = \Tr_{\reg{B}} \Big(\Werner  \big(\Purify \big(\rho^{\otimes n}\big) \big) \Big) = \Tr_{\reg{B}} \Big(\Werner  \Big(\E_{\ket{\brho}} \big[\ketbra{\brho}^{\otimes n}\big] \Big) \Big) = \E_{\ket{\brho}} \Big[ \Tr_{\reg{B}} \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) \Big) \Big].
    \end{equation*}
    By concavity of the ``square-root fidelity'' \cite[Corollary 3.26]{Wat18}, we then have
    \begin{equation*}
        \sqrt{\Fid \Big(  \PCT(\rho^{\otimes n}) , \rho^{\otimes (n+k)}\Big)} \geq \E_{\ket{\brho}}\Bigg[ \sqrt{\Fid \Big( \Tr_{\reg{B}} \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) \Big), \rho^{\otimes (n+k)} \Big)} \Bigg].
    \end{equation*}
    Next, by data processing of fidelity \cite[Theorem 3.27]{Wat18}, 
    \begin{align*}
        \Fid \Big( \Tr_{\reg{B}} \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) \Big), \rho^{\otimes (n+k)} \Big) & = \Fid \Big( \Tr_{\reg{B}} \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) \Big), \Tr_{\reg{B}}\big(\ketbra{\brho}^{\otimes (n+k)}\big) \Big) \\
        & \geq \Fid \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) , \ketbra{\brho}^{\otimes (n+k)}\Big).
    \end{align*}
    Then, by \Cref{lem:Werner_optimality,lem:ratio_of_symmetric_subspace_dimensions}, we have
    \begin{equation*}
        \Fid \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) , \ketbra{\brho}^{\otimes (n+k)}\Big) = \frac{D[n]}{D[n+k]} \geq 1 - \frac{kD}{n} = 1 - \frac{krd}{n}. 
    \end{equation*}
    Since this holds for all $\ket{\brho}$, we obtain
    \begin{equation*}
        \Fid \Big(  \PCT(\rho^{\otimes n}) , \rho^{\otimes (n+k)}\Big) \geq \Bigg( \E_{\ket{\brho}} \Bigg[ \sqrt{\Fid \Big( \Werner\big(\ketbra{\brho}^{\otimes n} \big) , \ketbra{\brho}^{\otimes (n+k)}\Big)} \Bigg] \Bigg)^2 \geq 1 - \frac{krd}{n}. 
    \end{equation*}
    Taking $n = \lceil krd/\eps \rceil$ makes this at least $1 - \eps$. This completes the proof.
\end{proof}

\subsection{Lower bounds via projector cloning}

In this section we prove the following result, which shows that rank-$r$ projector states are among the hardest rank-$r$ states to clone. Throughout, $P \in \C^{d \times d}$ will be a rank-$r$ projector, and $\rho = P/r$ the corresponding projector state. We will continue to use the shorthand $m = n+k$.

\begin{proposition}[A lower bound for cloning projector states; \Cref{prop:projector_lower_bound_tech_overview}, restated]\label{prop:projector_lower_bound}
Any channel $\calC: \states(\C^d)^{\otimes n} \to \states(\C^d)^{\otimes m}$ which clones rank-$r$ projector states to fidelity $1-\eps$ requires at least $n = \Omega(krd/\epsilon)$ copies as input, for $d \geq 2$, $r \leq d/2$, and $\epsilon \leq 1/16$. 
\end{proposition}

We note that restrictions of the form $d \geq 2$, $r < d$ and $\epsilon < 1$ are necessary to avoid cases where you can easily clone for trivial reasons: $d=1$ or $r = d$ or $\epsilon = 1$. We have not tried to optimize either of the restrictions on $r$ or $\eps$, as these will suffice for our purposes.

The remainder of the section is devoted to this statement's proof. Our argument is organized into five main steps.

\paragraph{Step 1.} We first reduce from fidelity, which is nonlinear, to a linear figure of merit, which will be easier to work with. For a quantum state $\sigma$ and a projector $\Pi$, we define the \emph{overlap} as the quantity $\tr(\sigma \cdot \Pi )$. The overlap is a simple quantity, and its utility lies in the following fact. 

\begin{lemma}\label{lem:reduction_from_fidelity_to_overlap}
    Let $\Pi \in \C^{d \times d}$ be a projector of rank $R$, and $\sigma \in \C^{d \times d}$ a quantum state. Then we have 
    \begin{equation*}
        \Fid( \sigma, \Pi/R) \leq \tr( \sigma \cdot \Pi).
    \end{equation*}
\end{lemma}

\begin{proof}
    Let $\{\lambda_i\}_{i \in [d]}$ be the eigenvalues of the Hermitian matrix $\Pi \cdot \sigma \cdot \Pi$, ordered decreasingly. Since $\Pi$ has rank $R$, at most $R$ of these eigenvalues are nonzero. Then by Cauchy-Schwarz,
    \begin{align*}
        \Fid(\sigma, \Pi/R) = \tr( \sqrt{\sqrt{ \Pi/R} \cdot \sigma \cdot \sqrt{\Pi/R}} )^2 = \frac{1}{R} \tr( \sqrt{\Pi \cdot \sigma \cdot \Pi})^2 = \frac{1}{R} \Big( \sum_{i=1}^R \sqrt{\lambda_i}\Big)^2 \leq \sum_{i=1}^{R} \lambda_i  & = \tr( \Pi \cdot \sigma \cdot \Pi) \\ & = \tr(\sigma \cdot \Pi). \qedhere
    \end{align*}
\end{proof}

With cloning, we seek to maximize the fidelity between the projector state $\rho^{\otimes m}$ and the output of our channel $\calC(\rho^{\otimes n})$. So, setting $\Pi \leftarrow P^{\otimes m}$ and $\sigma \leftarrow \calC(\rho^{\otimes n})$, we find 
\begin{equation*}
    \Fid \Big( \calC( \rho^{\otimes n}), \rho^{\otimes m} \Big) \leq \tr\Big( \calC (\rho^{\otimes n} ) \cdot P^{\otimes m} \Big).
\end{equation*}
In particular, if we want to prove that $\Fid (\calC( \rho^{\otimes n}), \rho^{\otimes m} ) \geq 1-\eps$ (for all $\rho$) implies a lower bound on $n$, it suffices to show instead that $\tr(\calC (\rho^{\otimes n} ) \cdot P^{\otimes m} ) \geq 1-\eps$ (for all $\rho$) implies a lower bound on $n$. 

\paragraph{Step 2.} Our next step is to reduce from generic channels to \emph{permutation-invariant} channels. This restriction is without loss of generality, due to the following lemma, which shows that for any channel $\calC$, there exists a permutation-invariant channel $\overline{\calC}$ which performs the same on any input $\rho^{\otimes n}$. 

\begin{lemma} \label{lem:reduction_to_perm_invariant}
    Let $\calC: \states(\C^d)^{\otimes n} \to \states(\C^d)^{\otimes m}$ be any channel. There exists a permutationally invariant channel $\overline{\calC}$ such that for any $P$,
    \begin{equation*}
        \tr\Big( \overline{\calC}(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) = \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big).
    \end{equation*}
    In particular, $\calC$ and $\overline{\calC}$ have the same minimum overlap, and the same average overlap.
\end{lemma}

\begin{proof}
    To obtain $\overline{\calC}$ from $\calC$, conjugate the input and output by random permutations of the appropriate size. That is:
    \begin{equation*}
        \overline{\calC}(X) \coloneq \frac{1}{m! \cdot n!} \sum_{\substack{\pi \in S_{m}\\ \sigma \in S_n}} \calP(\pi) \cdot \Big( \calC \big( \calP(\sigma) \cdot X \cdot \calP(\sigma)^\dagger \big)\Big) \cdot \calP(\pi)^\dagger.
    \end{equation*}
    Note that any permutation of the input and output registers can be absorbed into $\sigma$ and $\pi$ respectively, so that $\overline{\calC}$ is permutation-invariant. For inputs of the form $X = \rho^{\otimes n}$, we have
        $\calP(\sigma) \cdot \rho^{\otimes n} \cdot \calP(\sigma)^\dagger = \rho^{\otimes n}, $
    so that $\overline{\calC}(\rho^{\otimes n})$ simplifies:
    \begin{equation*}
        \overline{\calC}(\rho^{\otimes n}) =\frac{1}{m! } \sum_{\pi \in S_{m}} \calP(\pi) \cdot  \calC ( \rho^{\otimes n} )\cdot \calP(\pi)^\dagger.
    \end{equation*}
    However, since 
        $\calP(\pi)^\dagger \cdot P^{\otimes m} \cdot \calP(\pi) = P^{\otimes m}$
    as well, we have 
    \begin{equation*}
        \tr\Big( \overline{\calC}(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) = \frac{1}{m!} \sum_{\pi \in S_m} \tr\Big( \calC(\rho^{\otimes n}) \cdot \big(\calP(\pi)^\dagger \cdot P^{\otimes m} \cdot \calP(\pi)\big) \Big) = \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big).
    \end{equation*}
    This completes the proof. 
\end{proof}

Therefore, the best possible worst-case overlap is attained by a channel which is permutational-invariant. So, we can assume an overlap-optimal cloner has this property. 







\paragraph{Step 3.} We now show that the cloning performance of a permutation-invariant channel can be upper bounded cleanly. 

\begin{lemma} \label{lem:symmetric_channels_perfomance_upper_bounded}
    Let $\calC: \states(\C^d)^{\otimes n} \to \states(\C^d)^{\otimes m}$ be any permutation-invariant channel. Then we have
    \begin{equation*}
        \min_P \Big[ \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) \Big] \leq \sum_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}} \frac{\dim(\calP_\lambda) \cdot \dim(\calQ^d_\lambda)}{r^n} \cdot \max_{ \substack{\mu \vdash m \\ \ell(\mu) \leq r}} \norm{ \int_P q_\lambda(P)^T \otimes q_\mu(P) \cdot \dP }_\infty.
    \end{equation*}
\end{lemma}

\begin{proof}
We begin by passing to Choi-Jamiołkowski (CJ) states:
\begin{equation*}
    \tr \Big( \calC (\rho^{\otimes n}) \cdot P^{\otimes m} \Big) = \tr\Big( J({\calC}) \cdot \big(\rho^{T, \otimes n} \otimes P^{\otimes m} \big)\Big) = \frac{1}{r^n} \cdot \tr\Big( J({\calC}) \cdot \big(P^{T, \otimes n} \otimes P^{\otimes m}\big) \Big),
\end{equation*}
where $J({\calC})$ is the CJ state corresponding to $\calC$. Now, since $\calC$'s \emph{worst-case overlap} is at most its \emph{average-case} overlap,
\begin{equation}
    \min_P \Big[ \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) \Big] \leq \frac{1}{r^n} \cdot \tr( J({\calC}) \cdot \int_P P^{T,\otimes n} \otimes P^{\otimes m} \cdot \dP ). \label{eq:trace_choi_projector_integral}
\end{equation}
Here, $\dP$ is the measure on projectors induced by the Haar measure. We will rewrite the final trace in the Schur basis, starting with
\begin{equation*}
    \Big( \Schur^{(d,n),*}  \otimes \Schur^{(d,m)}\Big) \cdot \Big( P^{T,\otimes n} \otimes P^{\otimes m} \Big) \cdot \Big( \Schur^{(d,n),*}  \otimes \Schur^{(d,m)}\Big)^\dagger = \bigoplus_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}}\bigoplus_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} I_{\calP_\lambda} \otimes I_{\calP_\mu} \otimes q_\lambda(P)^T \otimes q_\mu(P).
\end{equation*}
In the same basis, since $\calC$ is permutation invariant, $J({\calC})$ commutes with permutations on both the input and output registers, and is therefore proportional to the identity on the permutation registers by Schur's lemma. Thus, we have
\begin{equation*}
    \Big( \Schur^{(d,n),*}  \otimes \Schur^{(d,m)}\Big) \cdot  J(\calC) \cdot \Big( \Schur^{(d,n),*}  \otimes \Schur^{(d,m)}\Big)^\dagger = \bigoplus_{\substack{\lambda \vdash n \\ \mu \vdash m}} I_{\calP_\lambda} \otimes \frac{I_{\calP_\mu}}{\dim(\calP_\mu)} \otimes J(\calC)_{\lambda \mu},
\end{equation*}
with $J(\calC)_{\lambda \mu}$ some PSD matrix on $\calQ^d_\lambda \otimes \calQ^d_\mu$. We have inserted the factor of $\dim(\calP_\mu)$ for convenience: now trace-preservation of $\calC$ is equivalent to $\sum_{\mu} \tr_{\calQ^d_\mu} (J(\calC)_{\lambda \mu}) = I_{\calQ^d_\lambda}$ by \cite[Theorem 2.36, Item 3]{Wat18}. Hence we obtain
\begin{align*}
    \eqref{eq:trace_choi_projector_integral} & = \sum_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}} \sum_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} \frac{\dim(\calP_\lambda)}{r^n} \cdot \tr \Big( J(\calC)_{\lambda \mu} \cdot \int_P q_\lambda(P)^T \otimes q_\mu(P) \cdot \dP\Big) \\
    & \leq \sum_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}} \sum_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} \frac{\dim(\calP_\lambda)}{r^n} \cdot \tr \Big( J(\calC)_{\lambda \mu}\Big) \cdot \max_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} \norm{\int_P q_\lambda(P)^T \otimes q_\mu(P) \cdot \dP}_\infty \\
    & \leq \sum_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}}  \frac{\dim(\calP_\lambda)}{r^n} \cdot \tr\big( I_{\calQ^d_\lambda}\big) \cdot \max_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} \norm{\int_P q_\lambda(P)^T \otimes q_\mu(P) \cdot \dP}_\infty \\
    & \leq  \sum_{\substack{\lambda \vdash n \\ \ell(\lambda) \leq r}} \frac{\dim(\calP_\lambda) \cdot \dim(\calQ^d_\lambda)}{r^n}  \cdot \max_{\substack{\mu \vdash m \\ \ell(\mu) \leq r}} \norm{\int_P q_\lambda(P)^T \otimes q_\mu(P) \cdot \dP}_\infty.
\end{align*}
This completes the proof.
\end{proof}

We can also reinterpret the bound of \Cref{lem:symmetric_channels_perfomance_upper_bounded} in terms of weak Schur sampling. Given a state of the form $P/r$, the probability of sampling $\blambda \sim \WSS_n(1^r/r)$ is $\dim(\calP_\lambda) \cdot \dim(\calQ^r_\lambda)/r^n$ for any $\lambda$ with $\ell(\lambda) \leq r$, so that the bound from this lemma becomes:
\begin{equation} \label{eq:bound_in_terms_of_WSS}
        \min_P \Big[ \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) \Big] \leq \E_{\blambda} \bigg[ \frac{s_{\blambda}(1^d)}{s_{\blambda}(1^r)} \cdot \max_{ \substack{\mu \vdash m \\ \ell(\mu) \leq r}} \norm{ \int_P q_{\blambda}(P)^T \otimes q_\mu(P) \cdot \dP }_\infty \bigg].
\end{equation}

\paragraph{Step 4.} We now show that the choice of $\mu$ maximizing this upper bound, given $\lambda$, is $\mu = \lambda + k \cdot e_1$. Our main tool for this step is the following bound (in the PSD order) on the partially-transposed integral. We defer the proof to \Cref{sec:partially_transposed_integral_bound}, since it is relatively involved.

\begin{lemma}[The partially-transposed integral bound] \label{lem:transposed_integral}
    Let $\lambda \in \Par(n,d)$ and $\mu \in \Par(m,d)$, with $\ell(\lambda) \leq r$ and $\ell(\mu) \leq r$. Then we have
    \begin{equation*}
        \int q_{\lambda}^d(P)^T \otimes q_{\mu}^d(P) \cdot \dP \preceq \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_{\calQ^d_\lambda} \otimes I_{\calQ^d_\mu}. 
    \end{equation*}

\end{lemma}

We now analyze the products that appear in this upper bound. 

\begin{lemma} \label{lem:best_mu_is_lambda+ke1}
    Fix $\lambda \in \Par(n,d)$ with $\ell(\lambda) \leq r$. Then the ratio

    $s_{\lambda \cup \mu}(1^r)/s_{\lambda \cup \mu}(1^d)$
    is maximized over all $\mu \in \Par(n+k,d)$ by the choice $\mu = \lambda + k \cdot e_1$. For this $\mu$, we have
    \begin{equation*}
         \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} = \frac{s_{\lambda}(1^r)}{s_{\lambda }(1^d)} \cdot \prod_{j=1}^{k} \frac{r + \lambda_1 + j - 1}{d + \lambda_1 + j - 1}.
    \end{equation*}
\end{lemma}

\begin{proof}
    For fixed $\lambda$, consider the set of products of the form
    \begin{equation*}
        \frac{s_\lambda(1^d)}{s_\lambda(1^r)} \cdot \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)}
    \end{equation*}
    for some $\mu \vdash n+k$. The denominator is nonzero since $\ell(\lambda) \leq r$. We can also assume $\ell(\mu) \leq r$, since otherwise $s_{\lambda \cup \mu}(1^r) = 0$. We first show that this product is maximized when $\mu = \lambda + k \cdot e_1$. Using the hook-content formula, Eq. \eqref{eq:hook_content_formula}, we have
    \begin{equation*}
        \frac{s_\lambda(1^d)}{s_\lambda(1^r)} \cdot \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} = \Big( \prod_{\Box \in \lambda} \frac{d + c(\Box)}{r + c(\Box)} \Big) \cdot \Big( \prod_{\Box \in \lambda \cup \mu} \frac{r + c(\Box)}{d + c(\Box)} \Big) = \prod_{\Box \in \mu \setminus \lambda} \frac{r + c(\Box)}{d+ c(\Box)}. 
    \end{equation*}
    We note that (i) each term in the product is positive, since $c(\Box) > -r$ for any $\Box \in \mu \setminus \lambda$, (ii) each term is at most $1$, and (iii) each term is an increasing function of the content. 
    Now consider any ordering of the boxes in $\mu \setminus \lambda$, such that after adding the first $j$ boxes to $\lambda$, we still have a valid Young diagram, for all $j$. The box added in the $j$-th step, $\Box_j$, has content at most $\lambda_1+j-1$, obtained by inserting that box into the first row. For $j \in [k]$, we therefore bound the corresponding term as
    \begin{equation*}
        \frac{r+c(\Box_j)}{d+c(\Box_j)} \leq \frac{r + (\lambda_1+j-1)}{d + (\lambda_1+j-1)}.
    \end{equation*}
    For the remaining boxes, we bound this term trivially by $1$. Thus,
    \begin{equation*}
        \prod_{\Box \in \mu \setminus \lambda} \frac{r + c(\Box)}{d+ c(\Box)} \leq \prod_{j=1}^{k} \frac{r + (\lambda_1 + j - 1)}{d + (\lambda_1 + j - 1)}.
    \end{equation*}
    This is exactly the product attained by setting $\mu = \lambda + k \cdot e_1$, as in this case $|\mu \setminus \lambda| = k$, and the $k$ boxes are in the first row. This completes the proof. \qedhere
\end{proof}

\paragraph{Step 5.} Finally, we prove the proposition. From the previous two steps, we have that
\begin{equation*}
    \min_{P} \Big[ \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) \Big] \leq \E_{\blambda} \bigg[ \prod_{j=1}^{k} \frac{r + \blambda_1 + j - 1}{d + \blambda_1 + j - 1} \bigg].
\end{equation*}
If we have a rank-$r$ projector cloning channel $\calC$ which clones to global fidelity at least $1-\eps$ for any $P$, then we moreover have
\begin{equation*}
    1 - \epsilon \leq \min_{P} \Big[ \tr\Big( \calC(\rho^{\otimes n}) \cdot P^{\otimes m} \Big) \Big] \leq \E_{\blambda} \bigg[ \prod_{j=1}^{k} \frac{r + \blambda_1 + j - 1}{d + \blambda_1 + j - 1} \bigg]
\end{equation*}
We will now show that this implies the desired lower bound on $n$, for certain ranges of the parameters $d, r, \eps$. 

\begin{lemma} \label{lem:lower_bound_from_WSS}
    Suppose $\blambda \sim \WSS_n(1^r/r)$, and we have the inequality
    \begin{equation*}
    1 - \eps \leq \E_{\blambda} \bigg[ \prod_{j=1}^{k}\frac{r+\blambda_1+j-1}{d + \blambda_1+j-1}\bigg] 
    \end{equation*}
    Then if $d \geq 2$, $r \leq d/2$ and $\epsilon \leq 1/16$, we must have 
    \begin{equation*}
        n \geq \frac{1}{8} \cdot \frac{krd}{\eps}.
    \end{equation*}
\end{lemma}

\begin{proof}
We start by rewriting
\begin{equation*}
    \E_{\blambda} \bigg[ \prod_{j=1}^{k}\frac{r+\blambda_1+j-1}{d + \blambda_1+j-1}\bigg] =  \E \bigg[ \prod_{j=1}^{k} \Big( 1 - \frac{d-r}{d + \blambda_1 + j-1} \Big)\bigg].
\end{equation*}
We will now use the chain of inequalities: for $u_j \in [0,1]$,
\begin{equation*}
    \prod_{j=1}^k ( 1 - u_j ) \leq \prod_{j=1}^{k} \frac{1}{1+u_j} \leq \frac{1}{1 + \sum_{j=1}^k u_j} \leq \frac{1}{1 + k \cdot \min(u_j)}.
\end{equation*}
In particular, we will set $u_j \leftarrow (d-r)/(d + \blambda_1 + j - 1)$, noting that $\blambda_1 + j - 1 \geq 0$ so that $u_j \leq (d-r)/d < 1$ as we require. Note also that $\min u_j = (d-r)/(d+\blambda_1 + k - 1)$. Then we get
\begin{align*}
    \E \bigg[ \prod_{j=1}^{k} \Big( 1 - \frac{d-r}{d + \blambda_1 + j-1} \Big)\bigg] \leq \E \bigg[ \frac{1}{1 + \frac{k(d-r) }{ ( d + \blambda_1 + k-1)}}\bigg] & = 1 - \E \bigg[ \frac{k(d-r)}{d + \blambda_1 + k - 1 + k(d-r)}\bigg] \\
    & \leq 1 - \frac{k(d-r)}{d + \E[\blambda_1] + k-1 + k(d-r)}.
\end{align*}
The last inequality is Jensen's. We now use 
\begin{equation*}
    \E [ \blambda_1] \leq \frac{n}{r} + 2 \sqrt{n} \leq \frac{2n}{r} + r.
\end{equation*}
The first inequality is \cite[Theorem 5.2]{OW17a}, and the second is AM-GM, applied as $2\sqrt{n} = 2\sqrt{ r \cdot (n/r)}$. Then we have
\begin{equation*}
    1 - \epsilon \leq 1 - \frac{k(d-r)}{d + \E[\blambda_1] + k-1 + k(d-r)} \leq 1 - \frac{k(d-r)}{d + \frac{2n}{r}  + r + k-1 + k(d-r)}.
\end{equation*}
We can rearrange this inequality to find a lower bound on $n$:
\begin{equation*}
    n \geq \frac{1}{2} \cdot \bigg(\frac{kr(d-r)}{\eps} - r\Big(d + r + k -1 + k(d-r) \Big) \bigg) \geq \frac{1}{2} \cdot \bigg( \frac{kr (d-r)}{\eps} - 4krd\bigg).
\end{equation*}
Since $r \geq 1$, we need $d \geq 2$ for this bound to be nontrivial. Then, if $r \leq d/2$, we have $kr(d-r)/\eps \geq krd/2\eps$. Finally, because $\eps \leq 1/16$, we have $4krd \leq krd/4\eps$. For these parameter restrictions, we then get
\begin{equation*}
    n \geq \frac{1}{8} \cdot \frac{krd}{\eps}. \qedhere
\end{equation*}
\end{proof}
This lemma completes the proof of \Cref{prop:projector_lower_bound}. 



\subsection{Sample-optimal cloning of mixed states}

Here, we combine our ingredients to conclude our main result, which we restate here for the reader's convenience. 

\begin{theorem}[The PCT cloner is sample-optimal; \Cref{thm:main_result_intro}, restated] 
    Suppose $\calC: \states(\C^d)^{\otimes n} \to \states(\C^d)^{\otimes (n+k)}$ is a cloning channel such that
    \begin{equation*}
         \Fid \big(  \calC(\rho^{\otimes n}) , \rho^{\otimes (n+k)}\big) \geq 1-\eps,
    \end{equation*}
    for all states $\rho$ of rank at most $r$. Then we must have $n = \Omega(krd/\eps)$, for $d \geq 2$, and $\epsilon \leq \epsilon_0$, where $\epsilon_0$ is a universal constant. Moreover, the PCT cloner achieves this guarantee with $n = O(krd/\eps)$ copies. Thus, the sample complexity of cloning $k$ additional copies of any unknown rank-$r$ input state $\rho^{\otimes n}$ to fidelity $1-\eps$ is $\Theta(krd/\eps)$. 
\end{theorem}

\begin{proof}
    In \Cref{prop:upper_bound_PCT}, we show the PCT cloner attains the upper bound. In \Cref{prop:projector_lower_bound}, we show that even when promised the input is a rank-$r$ projector state, we require $n = \Omega(krd/\eps)$ copies for $d \geq 2$, $r \leq d/2$, and $\epsilon \leq 1/16$. The lower bound for generic rank follows by considering projector states of rank $\min(r, d/2)$. This completes the proof.
\end{proof}

\subsection{The partially-transposed integral} \label{sec:partially_transposed_integral_bound}

 Throughout this section, it will be useful to introduce some shorthand to simplify our expressions. In particular, we will adopt the convention of writing $X_\lambda$ as shorthand for $q_\lambda^d(X)$. The dimension $d$ can be inferred from $\lambda$, since we will always specify the number of parts of $\lambda$, e.g.\ as $\lambda \in \Par(-,d)$. As an example, we will write $I_\lambda$ as shorthand for $q^d_\lambda(I) = I_{\calQ^d_\lambda}$. 

We now circle back to the partially-transposed integral, and prove the bound we claimed earlier, which we restate for convenience.

\begin{lemma}[The partially-transposed integral bound; \Cref{lem:transposed_integral} restated] \label{lem:transposed_integral_2}
    Let $\lambda \in \Par(-,d)$ and $\mu \in \Par(-,d)$. Then
    \begin{equation*}
        \int P^T_\lambda \otimes P_\mu \cdot \dP   \preceq \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_{\lambda} \otimes I_{\mu} = \Phi_{\lambda \cup \mu}^{(d,r)} \cdot I_\lambda \otimes I_\mu. 
    \end{equation*}

\end{lemma}

We take a somewhat indirect approach. We start by considering the partial transpose of this integral, resulting in both terms in the integrand un-transposed. The un-transposed integral bound reads
\begin{equation} \label{eq:transposed_bound}
        \int P_\lambda \otimes P_\mu \cdot \dP \preceq \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_{\lambda} \otimes I_{\mu}.
\end{equation}
This bound itself is actually relatively easy to show, and follows from the Littlewood--Richardson rule. However, even with \Cref{eq:transposed_bound} we cannot conclude \Cref{lem:transposed_integral}, as it is not necessarily true that $X \preceq Y$ implies $X^\Gamma \preceq Y^\Gamma$.\footnote{For instance, take $X = 0$ and $Y = \ketbra{\Omega}$, with $\ket{\Omega} = \ket{00} + \ket{11}$. Then $X^\Gamma = 0$ and $Y^\Gamma = \mathrm{SWAP}$, which has both positive and negative eigenvectors.} We overcome this by showing a stronger structural result: the difference between the right- and left-hand sides is not only PSD, but separable. Defining
\begin{equation*}
    \Delta_{\lambda \mu} \coloneq \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_{\lambda} \otimes I_{\mu} - \int P_\lambda \otimes P_\mu \cdot \dP, 
\end{equation*}
we will show the following result.

\begin{proposition} \label{prop:untransposed_bound}
    Let $\lambda \in \Par(-,d)$ and $\mu \in \Par(-,d)$. Then we have $$\Delta_{\lambda \mu} \in \Sep_+(\calQ_{\lambda}^d : \calQ_{\mu}^d).$$ 
    That is, $\Delta_{\lambda \mu}$ is a nonnegative linear combination of matrices of the form $A \otimes B$, where $A$ acts on $\calQ^d_\lambda$, $B$ acts on $\calQ^d_\mu$, and $A, B \succeq 0$. 
\end{proposition}

From here, we can prove the partially-transposed integral bound straightforwardly.

\begin{proof}[Proof of \Cref{lem:transposed_integral}]
    Since $A^T$ is PSD if $A$ is, we have
    \begin{equation*}
        \Sep_+(\calQ_{\lambda}^d : \calQ_{\mu}^d)^\Gamma \subseteq \Sep_+(\calQ_{\lambda}^d : \calQ_{\mu}^d).
    \end{equation*}
    Thus, $\Delta_{\lambda \mu}^\Gamma \in \Sep_+(\calQ_{\lambda}^d : \calQ_{\mu}^d)$, and in particular,
    \begin{equation*}
        \Delta_{\lambda \mu}^\Gamma = \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_\lambda \otimes I_\mu - \int P_\lambda^T \otimes P_\mu \cdot \dP \succeq 0.
    \end{equation*}
    This completes the proof.
\end{proof}

The rest of the section is devoted to establishing the proposition. We will start by developing notation, defining useful quantities, and establishing some lemmas.

\subsubsection{Background for the proof}

We will write $S_{\lambda \mu}^{(d,r)}$ as shorthand for the integral appearing in \Cref{eq:transposed_bound} ($S$ is for \emph{sum}). We note that $S^{(d,r)}_{\lambda \mu}$ can be rewritten as an integral over all possible rotations of a \emph{fixed} matrix: for any fixed rank-$r$ projector $P^{(r)}_0 \in \C^{d \times d}$,
\begin{equation} \label{eq:S}
    S^{(d,r)}_{\lambda \mu} = \int_{U \in U(d)} \big( U_\lambda \otimes U_\mu \big) \cdot \big( P^{(r)}_{0,\lambda}  \otimes P^{(r)}_{0,\mu} \big) \cdot \big( U_\lambda \otimes U_\mu \big)^\dagger \cdot \dU, 
\end{equation}
It will be convenient to set $P^{(r)}_0 \leftarrow \sum_{i = d-r+1}^d \ketbra{i}$, i.e.\ $P^{(r)}_0$ is projection onto the \emph{last} $r$ standard basis vectors of $\C^d$.

\paragraph{A few useful projectors on $\calQ^d_\lambda$.} Let $\lambda \in \Par(-,d)$, and $\lambda' \in \Par(-,d)$ such that $\lambda'$ interlaces $\lambda$. We now define a few useful projectors on the space $\calQ^d_\lambda$. First, we define $\Pi_{\lambda' \subseteq \lambda}$ as the projector
\begin{equation*}
    \Pi_{\lambda' \subseteq \lambda} \coloneq \Proj\big\{ T \, : \,\sh(T_{\leq (d-1)}) = \lambda' \big\}. 
\end{equation*}
That is, $\Pi_{\lambda' \subseteq \lambda}$ projects only onto those SSYTs of shape $\lambda$ that, when you look only at the symbols less than $d$, has shape $\lambda'$. Note that $\sum_{\lambda'} \Pi_{\lambda' \subseteq \lambda} = I_\lambda$. Next, we define $\Pi^{(t)}_{\lambda}$ for $t \in [d]$ as the projector 
\begin{equation*}
    \Pi^{(t)}_{\lambda} \coloneq \Proj\big\{ T \, : \sh(T_{\leq(d-t)}) = \varnothing \big\}. 
\end{equation*}
In words: $\Pi^{(t)}_{\lambda}$ projects onto those SSYTs of shape $\lambda$ that are filled only by the \emph{last} $t$ symbols in the alphabet. Note that $\Pi^{(d)}_\lambda = I_\lambda$ and $\Pi^{(r)}_\lambda = (P_0^{(r)})_\lambda$. Finally, we define $\Pi^{(t)}_{\lambda' \subseteq \lambda}$ as the product of the two projectors above. That is, 
\begin{equation*}
    \Pi^{(t)}_{\lambda' \subseteq \lambda} \coloneq \Proj\big\{ T \, : \,\sh(T_{\leq (d-1)}) = \lambda' \; \mathrm{and} \; \sh(T_{\leq(d-t)}) = \varnothing \big\}. 
\end{equation*}

\paragraph{Embedding maps.} We also define embedding maps $E_{\lambda' \subseteq \lambda}$ that include $\calQ^{d-1}_{\lambda'} \hookrightarrow \calQ^d_\lambda$. Concretely
$E_{\lambda' \subseteq \lambda} \cdot \ket{T'} = \ket{T}$,
where $T$ is the SSYT of $\lambda$ such that $T_{\leq (d-1)} = T'$. We note the following relations which we will use later. First, for any $V \in U(d-1)$, viewed as an element of $U(d)$ by letting it act on the first $d-1$ basis vectors as $V$, and fixing $\ket{d}$, we have 
\begin{equation}\label{eq:aux_1}
    E_{\lambda' \subseteq \lambda} \cdot V_{\lambda'} = V_\lambda \cdot E_{\lambda' \subseteq \lambda}.
\end{equation}
Second, we have
\begin{equation}\label{eq:aux_2}
    E_{\lambda' \subseteq \lambda} \cdot I_{\lambda'} \cdot E_{\lambda' \subseteq \lambda}^\dagger = \Pi_{\lambda' \subseteq \lambda}. 
\end{equation}
Finally, 
\begin{equation}\label{eq:aux_3}
    E_{\lambda' \subseteq \lambda} \cdot \Pi^{(t-1)}_{\lambda'} \cdot E_{\lambda' \subseteq \lambda}^\dagger = \Pi^{(t)}_{\lambda' \subseteq \lambda}.
\end{equation}
To understand this last one, note that on the left-hand side, we are embedding all SSYTs of shape $\lambda'$ with alphabet $\{(d-1)-(t-1)+1, \dots, d-1\} = \{d-t+1, \dots, d-1\}$ into $\calQ^d_\lambda$, which gives us the right-hand side. We also note $\Pi^{(t)}_{\lambda} = \sum_{\lambda' \preceq \lambda} \Pi^{(t)}_{\lambda' \subseteq \lambda}$. 

For simpler notation, we will also introduce an \emph{embedding channel}, defined as $\calE_{\lambda' \subseteq \lambda}(X) \coloneq E_{\lambda' \subseteq \lambda} \cdot X \cdot E_{\lambda' \subseteq \lambda}^\dagger$. 

\paragraph{Lifting.} Finally, let $\mu \in \Par(-,d)$ as well, and let $\mu' \in \Par(-,d-1)$ such that $\mu' \preceq \mu$. Given any operator $X$ acting on $\calQ^{d-1}_{\lambda'} \otimes \calQ^{d-1}_{\mu'}$, we can use the embedding maps $E_{\lambda' \subseteq \lambda}$ and $E_{\mu' \subseteq \mu}$ to lift $X$ to an operator on $\calQ^d_\lambda \otimes \calQ^d_\mu$. In our case, it will be convenient to average the resulting operator over all possible rotations as well, so as to bear closer resemblance to $S_{\lambda\mu}$. Thus, we define the $\emph{lift}$ as the map
\begin{equation*}
    \Lift_{\lambda'\mu'}^{\lambda \mu}(X) \coloneq \int_{U \in U(d)} \big(U_{\lambda} \otimes U_\mu\big) \cdot \big(E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu} \big) \cdot X  \cdot \big(E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu} \big)^\dagger \cdot \big(U_{\lambda} \otimes U_\mu\big)^\dagger \cdot \dU.
\end{equation*}
A key observation is that if $X \in \Sep^+(\calQ^{d-1}_{\lambda'} : \calQ^{d-1}_{\mu'})$, then $\Lift_{\lambda'\mu'}^{\lambda \mu}(X) \in \Sep^+(\calQ^{d}_\lambda : \calQ^d_\mu)$. 

We can simplify our notation if we further introduce a \emph{twirling-by-unitaries channel}, given by \begin{equation*}
\calU_{\lambda \mu}(X) \coloneq \int_{U \in U(d)} (U_\lambda \otimes U_\mu) \cdot X \cdot (U_\lambda \otimes U_\mu)^\dagger \cdot \dU. 
\end{equation*}
Then 
\begin{equation*}
    \Lift_{\lambda'\mu'}^{\lambda \mu}(X) = \calU_{\lambda \mu} ( \calE_{\lambda' \subset \lambda} \otimes \calE_{\mu' \subset \mu} (X)). 
\end{equation*}

Our first key lemma gives a recursive formula for $I_\lambda \otimes I_\mu$, in terms of the lifts of operators of the form $I_{\lambda'} \otimes I_{\mu'}$, for intertwining diagrams $\lambda' \preceq \lambda$ and $\mu' \preceq \mu$. 

\begin{lemma} \label{lem:lift_recursion_identity}
    Fix $\lambda, \mu \in \Par(-,d)$, and $\lambda' \in \Par(-,d-1)$ with $\lambda' \preceq \lambda$. Then
        \begin{equation*}
            \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda'\mu'} \big( I_{\lambda'} \otimes I_{\mu'} \big) = \frac{s_{\lambda'}(1^{d-1})}{s_{\lambda}(1^d)} \cdot I_{\lambda} \otimes I_{\mu}.
        \end{equation*}
\end{lemma}

\begin{proof}
    From \Cref{eq:aux_2}, we have
    \begin{equation*}
        \big(E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu} \big) \cdot  \big( I_{\lambda'} \otimes I_{\mu'} \big) \cdot \big(E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu} \big)^\dagger = \Pi_{\lambda' \subseteq \lambda} \otimes \Pi_{\mu' \subseteq \mu}.
    \end{equation*}
    Thus, 
    \begin{align*}
        \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda'\mu'} \big( I_{\lambda'} \otimes I_{\mu'} \big) &  = \sum_{\mu' \preceq \mu} \int \big(U_{\lambda} \otimes U_\mu\big) \cdot \big( \Pi_{\lambda' \subseteq \lambda} \otimes \Pi_{\mu' \subseteq \mu}\big) \cdot \big(U_{\lambda} \otimes U_\mu\big)^\dagger \cdot \dU  \\
        & = \int \big(U_{\lambda} \otimes U_\mu\big) \cdot \big( \Pi_{\lambda' \subseteq \lambda} \otimes I_\mu \big) \cdot \big(U_{\lambda} \otimes U_\mu\big)^\dagger \cdot \dU \\
        & = \bigg( \int U_\lambda \cdot \Pi_{\lambda' \subseteq \lambda} \cdot U_\lambda^\dagger \cdot \dU \bigg) \otimes I_{\mu} \\
        & = \frac{s_{\lambda'}(1^{d-1})}{s_{\lambda}(1^d)} \cdot I_{\lambda} \otimes I_{\mu}. 
    \end{align*}
    The second step uses $\sum_{\mu' \preceq \mu} \Pi_{\mu' \subseteq \mu} = I_\mu$. The last step is Schur's lemma, where we have used $\tr(\Pi_{\lambda' \subseteq \lambda}) = \dim(\calQ^{d-1}_{\lambda'}) = s_{\lambda'}(1^{d-1})$. 
\end{proof}

Our second key lemma gives a similar recursive formula, except for the integral $S^{(d,r)}_{\lambda \mu}$. 

\begin{lemma} \label{lem:lift_recursion_integral}
    Fix $\lambda, \mu \in \Par(-,d)$, and $\lambda' \in \Par(-,d-1)$ such that $\lambda' \preceq \lambda$ and $\ell(\lambda') \leq r-1$. Then 
    \begin{equation*}
        S^{(d,r)}_{\lambda \mu} =  \frac{s_{\lambda}(1^{r})}{s_{\lambda'}(1^{r-1})} \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda'\mu'} \Big( S^{(d-1,r-1)}_{\lambda'\mu'} \Big).
    \end{equation*}
\end{lemma}

\newcommand{\dV}{\mathrm{d}V}
\newcommand{\dW}{\mathrm{d}W}

\begin{proof}

























    From \Cref{eq:S} and the fact that $P^{(r)}_{0,\lambda} = \Pi^{(r)}_{\lambda}$, we have
\begin{equation*}
    S_{\lambda \mu}^{(d,r)} = \int_{U \in U(d)} \big( U_\lambda \otimes U_\mu \big) \cdot \big( \Pi^{(r)}_\lambda  \otimes \Pi^{(r)}_{\mu} \big) \cdot \big( U_\lambda \otimes U_\mu \big)^\dagger \cdot \dU.
\end{equation*}
    Embed $U(r) \hookrightarrow U(d)$ by letting $W \in U(r)$ act nontrivially on the \emph{last} $r$ basis elements. Note then that
    \begin{equation} \label{eq:aux_4}
        \int_{W \in U(r)} W_\lambda \cdot \Pi_{\lambda' \subseteq \lambda}^{(r)} \cdot W_\lambda^\dagger \cdot \dW = \frac{\tr\big( \Pi^{(r)}_{\lambda' \subseteq \lambda} \big)}{s_\lambda(1^r)} \cdot \Pi^{(r)}_{\lambda} = \frac{s_{\lambda'}(1^{r-1})}{s_\lambda(1^r)} \cdot \Pi^{(r)}_{\lambda}. 
    \end{equation}
    In the above, we have used that $\Pi_{\lambda' \subseteq \lambda}^{(r)}$ is a sub-projector of $\Pi_{\lambda}^{(r)}$, and Schur's lemma, noting that the integral is $U(r)$-invariant on the support of $\Pi^{(r)}_\lambda$, a subspace isomorphic to $\calQ^r_\lambda$. Thus
    \begin{align}
         \frac{s_{\lambda'}(1^{r-1})}{s_\lambda(1^r)} \cdot S^{(d,r)}_{\lambda \mu} & = \frac{s_{\lambda'}(1^{r-1})}{s_\lambda(1^r)} \cdot  \int_{U \in U(d)} \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \Big( \Pi^{(r)}_\lambda \otimes \Pi^{(r)}_\mu \Big) \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU \nonumber \\
         & = \int_{U \in U(d)} \int_{W \in U(r)} \big((UW)_{\lambda} \otimes U_{\mu}\big)  \cdot \Big( \Pi^{(r)}_{\lambda' \subseteq \lambda} \otimes \Pi^{(r)}_\mu \Big) \cdot \big((UW)_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dW \cdot \dU \nonumber \\
         & = \int_{U \in U(d)} \int_{W \in U(r)} \big((UW)_{\lambda} \otimes (UW)_{\mu}\big)  \cdot \Big( \Pi^{(r)}_{\lambda' \subseteq \lambda} \otimes\Pi^{(r)}_\mu \Big) \cdot \big((UW)_{\lambda} \otimes (UW)_{\mu}\big)^\dagger \cdot \dW \cdot \dU \nonumber \\
         & = \int_{U \in U(d)} \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \Big( \Pi^{(r)}_{\lambda' \subseteq \lambda} \otimes \Pi^{(r)}_\mu \Big) \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU. \label{eq:halfway_through}
    \end{align}
    In the second step, we have used \Cref{eq:aux_4}. In the third step, we have used that $P_0^{(r)}$ is invariant under $W \in U(r)$, and hence $(P_0^{(r)})_\mu = \Pi^{(r)}_\mu$ is invariant under $W_\mu$. In the fourth step, we have used the right-invariance of the Haar measure, and redefined $UW \to U$. Finally, we use $\Pi^{(r)}_\mu = \sum_{\mu' \preceq \mu} \Pi^{(r)}_{\mu' \subseteq \mu}$, and \Cref{eq:aux_3} to get:
    \begin{align}
        \eqref{eq:halfway_through} 
        & = \sum_{\mu' \preceq \mu} \int_{U \in U(d)} \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \Big( \Pi^{(r)}_{\lambda' \subseteq \lambda} \otimes \Pi^{(r)}_{\mu' \subseteq \mu} \Big) \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU \nonumber \\
        & = \sum_{\mu' \preceq \mu} \int_{U \in U(d)} \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big) \cdot \Big( \Pi^{(r-1)}_{\lambda'} \otimes \Pi^{(r-1)}_{\mu'} \Big) \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big)^\dagger \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU. \label{eq:three-quarters-there}
    \end{align}
    Finally, we use the right-invariance of the Haar measure again, this time to re-insert a unitary $V \in U(d-1)$ as $U \to U \cdot V$ (viewing the action of $V$ on $U(d)$ as acting nontrivially only on the first $d-1$ basis elements), which we can then pass through the embedding maps using \Cref{eq:aux_1}. This gives us 

    \begin{align*}
        \eqref{eq:three-quarters-there} 
        & =\sum_{\mu' \preceq \mu} \int_{U \in U(d)} \int_{V \in U(d-1)} \big((UV)_{\lambda} \otimes (UV)_{\mu}\big)  \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big) \cdot \Big( \Pi^{(r-1)}_{\lambda'} \otimes \Pi^{(r-1)}_{\mu'} \Big) \cdot \\
        & \qquad \qquad \qquad \qquad \qquad \qquad  \qquad \qquad \quad \; \qquad \qquad \qquad  \qquad \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big)^\dagger \cdot \big((UV)_{\lambda} \otimes (UV)_{\mu}\big)^\dagger \cdot \dV \cdot \dU \\
        & = \sum_{\mu' \preceq \mu} \int_{U \in U(d)}  \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big) \cdot \\
        & \qquad \cdot \bigg( \int_{V \in U(d-1)} \big(V_{\lambda'} \otimes V_{\mu'}\big) \cdot \Big( \Pi^{(r-1)}_{\lambda'} \otimes \Pi^{(r-1)}_{\mu'} \Big) \cdot \big(V_{\lambda'} \otimes V_{\mu'}\big)^\dagger \cdot \dV \bigg) \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big)^\dagger \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU \\
        & = \sum_{\mu' \preceq \mu} \int_{U \in U(d)}  \big(U_{\lambda} \otimes U_{\mu}\big)  \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big)  \cdot S^{(d-1,r-1)}_{\lambda'\mu'}  \cdot \big( E_{\lambda' \subseteq \lambda} \otimes E_{\mu' \subseteq \mu}\big)^\dagger \cdot \big(U_{\lambda} \otimes U_{\mu}\big)^\dagger \cdot \dU \\
        & = \sum_{\mu' \preceq \mu} \Lift_{\lambda' \mu'}^{\lambda \mu}\Big(S^{(d-1,r-1)}_{\lambda'\mu'}\Big).
    \end{align*}
    This completes the proof. 

























\end{proof}

\paragraph{A Schur polynomial identity.} We will need one last technical lemma. For a diagram $\lambda \in \Par( - , d)$, write $\lambda^-$ for the diagram in $\Par(-, d-1)$ with $\lambda^- = (\lambda_2, \lambda_3, \dots, \lambda_d)$. 

\begin{lemma} \label{lem:lambda_minus_identity}
    Suppose $\lambda, \mu \in \Par(-, d)$, with $\lambda_1 \geq \mu_1$, and such that $\ell(\lambda) \leq r$ and $\ell(\mu) \leq r$. Then 
    \begin{equation*}
        \frac{s_{\lambda}(1^r)}{s_{\lambda}(1^d)} \cdot \frac{s_{\lambda^-}(1^{d-1})}{s_{\lambda^-}(1^{r-1})} = \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot \frac{s_{\lambda^-\cup \mu^-}(1^{d-1})}{s_{\lambda^- \cup \mu^-}(1^{r-1})}. 
    \end{equation*}
    Rearranging this equation gives:
    \begin{equation*}
        \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot \frac{s_{\lambda}(1^{d})}{s_{\lambda^-}(1^{d-1})} = \frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} \cdot \frac{s_{\lambda}(1^r)}{s_{\lambda^-}(1^{r-1})}.
    \end{equation*}
\end{lemma}

\begin{proof}
    By the hook-content formula, \Cref{eq:hook_content_formula}, we have
    \begin{equation*}
        \frac{s_{\lambda}(1^r)}{s_{\lambda}(1^d)} = \prod_{\Box \in \lambda} \frac{r + c(\Box)}{d + c(\Box)} = \bigg(\prod_{\Box \in \mathrm{Row}_1(\lambda)} \frac{r + c(\Box)}{d + c(\Box)}\bigg) \cdot \bigg(\prod_{\Box \notin \mathrm{Row}_1(\lambda)} \frac{r + c(\Box)}{d + c(\Box)}\bigg).
    \end{equation*}
    Here, we have split the product up by whether the box is in the first row of $\lambda$, or not. Now, we also have
    \begin{equation*}
        \frac{s_{\lambda^-}(1^{r-1})}{s_{\lambda^-}(1^{d-1})} = \prod_{\Box \in \lambda^-} \frac{(r-1) + c(\Box)}{(d-1) + c(\Box)} = \prod_{\Box \notin \mathrm{Row}_1(\lambda)} \frac{(r-1) + (c(\Box)+1)}{(d-1) + (c(\Box)+1)} = \prod_{\Box \notin \mathrm{Row}_1(\lambda)} \frac{r + c(\Box)}{d + c(\Box)}. 
    \end{equation*}
    The second equation holds because the boxes of $\lambda^-$ are in one-to-one correspondence with the boxes of $\lambda$ which are not in the first row -- simply shift those boxes of $\lambda$ up once. This shift increases the content of each box by one. Combining these two equations gives us
    \begin{equation*}
         \frac{s_{\lambda}(1^r)}{s_{\lambda}(1^d)} \cdot \frac{s_{\lambda^-}(1^{d-1})}{s_{\lambda^-}(1^{r-1})} = \prod_{\Box \in \mathrm{Row}_1(\lambda)} \frac{r + c(\Box)}{d + c(\Box)}. 
    \end{equation*}
    This ratio is well-defined since $\ell(\lambda) \leq r$, so that $\ell(\lambda^-) \leq r-1$. 
    Moreover, this equation holds not only for $\lambda$, but for any diagram with length at most $r$. In particular, $\lambda \cup \mu$ has this property, and so we also have 
    \begin{equation*}
         \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot \frac{s_{(\lambda\cup \mu)^-}(1^{d-1})}{s_{(\lambda \cup \mu)^-}(1^{r-1})} = \prod_{\Box \in \mathrm{Row}_1(\lambda \cup \mu)} \frac{r + c(\Box)}{d + c(\Box)}. 
    \end{equation*}
    The lemma then follows from two observations: (i) $\lambda$ and $\lambda \cup \mu$ have the same boxes in their first row, since $\lambda_1 \geq \mu_1$; and (ii) $(\lambda \cup \mu)^- = \lambda^- \cup \mu^-$. 
\end{proof}

\subsubsection{Proving \Cref{prop:untransposed_bound}}

We are now ready to prove the proposition, which we restate here for convenience.

\begin{proposition}[\Cref{prop:untransposed_bound}, restated]
    Let $\lambda \in \Par(-,d)$ and $\mu \in \Par(-,d)$. Then we have $$\Delta_{\lambda \mu} \in \Sep_+(\calQ_{\lambda}^d : \calQ_{\mu}^d).$$ 
\end{proposition}

\begin{proof}
    First, we can assume $\ell(\lambda) \leq r$ and $\ell(\mu) \leq r$, since otherwise $\Delta_{\lambda \mu} = 0$. For example, if $\ell(\lambda) > r$, then $P_\lambda = 0$, which makes the integral vanish, and also $\ell(\lambda \cup \mu) \geq \ell(\lambda) > r$, which makes $s_{\lambda \cup \mu}(1^r) = 0$. Thus $\Delta_{\lambda \mu} = 0$, and the case where $\ell(\mu) > r$ is similar.

    We proceed by induction. Our base case will be $r=1$ and $d \geq r$ arbitrary. Assume $\mu_1 \leq \lambda_1$. Then since $\lambda$ and $\mu$ are just one-row diagrams, $\mu \subseteq \lambda$, and moreover, $\lambda \cup \mu = \lambda$. We then have
    \begin{align*}
        \Delta_{\lambda \mu} & = \Big( \frac{s_{\lambda}(1^r)}{s_{\lambda}(1^d)} \cdot I_{\lambda} \otimes I_{\mu}\Big) - \Big( \int q_\lambda^d(P) \otimes q^d_\mu(P) \cdot \dP \Big) \\
        & = \Big( \int q_\lambda^d(P) \cdot \dP \Big) \otimes I_\mu - \Big( \int q_\lambda^d(P) \otimes q^d_\mu(P) \cdot \dP \Big) \\
        & = \int q_\lambda^d(P) \otimes \big( I_\mu - q^d_\mu(P) \big) \cdot \dP. 
    \end{align*}
    Since $q^d_\mu(P) \preceq I_\mu$, we have $\Delta_{\lambda \mu} \in \Sep_+( \calQ^d_\lambda : \calQ^d_\mu)$, as we wanted to show. The case where $\mu_1 \geq \lambda_1$ is symmetric. 

    Now assume we have shown the result for rank $r-1$ and arbitrary dimension at least $r-1$. We will prove the result for rank $r$ and dimension $d \geq r$. We also assume $\lambda_1 \geq \mu_1$ --- the proof is symmetric in the other case. We have
    \begin{align*}
        \Delta_{\lambda \mu} & =  \frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot I_{\lambda} \otimes I_{\mu}  - S^{(d,r)}_{\lambda \mu} \\
        & = \bigg(\frac{s_{\lambda \cup \mu}(1^r)}{s_{\lambda \cup \mu}(1^d)} \cdot \frac{s_{\lambda}(1^{d})}{s_{\lambda^-}(1^{d-1})} \cdot \sum_{\mu'\preceq \mu}\Lift^{\lambda \mu}_{\lambda^-\mu'} \Big( I_{\lambda^-} \otimes I_{\mu'} \Big) \bigg) - \bigg( \frac{s_{\lambda}(1^r)}{s_{\lambda^-}(1^{r-1})} \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda^-\mu'} \Big(  S^{(d-1,r-1)}_{\lambda^-\mu'}\Big) \bigg) \\
        & = \bigg(\frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} \cdot \frac{s_{\lambda}(1^r)}{s_{\lambda^-}(1^{r-1})} \cdot \sum_{\mu'\preceq \mu}\Lift^{\lambda \mu}_{\lambda^-\mu'} \Big( I_{\lambda^-} \otimes I_{\mu'} \Big) \bigg) - \bigg( \frac{s_{\lambda}(1^r)}{s_{\lambda^-}(1^{r-1})} \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda^-\mu'} \Big(  S^{(d-1,r-1)}_{\lambda^-\mu'}\Big) \bigg) \\
        & = \frac{s_{\lambda}(1^r)}{s_{\lambda^-}(1^{r-1})} \cdot \sum_{\mu' \preceq \mu} \Lift^{\lambda \mu}_{\lambda^-\mu'} \bigg( \frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} \cdot I_{\lambda^-} \otimes I_{\mu'} - S^{(d-1,r-1)}_{\lambda^-\mu'} \bigg).
    \end{align*}
    The second step above follows by applying \Cref{lem:lift_recursion_identity,lem:lift_recursion_integral}, with $\lambda' \leftarrow \lambda^-$. The third step uses \Cref{lem:lambda_minus_identity}. The term appearing inside the summand's lift can be rewritten in terms of $\Delta_{\lambda^- \mu'}$:
    \begin{equation} \label{eq:almost_there}
        \frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} \cdot I_{\lambda^-} \otimes I_{\mu'} - S^{(d-1,r-1)}_{\lambda^-\mu'}  = \bigg(\frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} - \frac{s_{\lambda^-\cup \mu'}(1^{r-1})}{s_{\lambda^- \cup \mu'}(1^{d-1})} \bigg) \cdot I_{\lambda^-} \otimes I_{\mu'} + \Delta_{\lambda^- \mu'}.
    \end{equation}
    The term on the far right is in $\Sep_+(\calQ^{d-1}_{\lambda^-} : \calQ^{d-1}_{\mu'})$ by our inductive hypothesis, and therefore lifts to an element of $\Sep_+(\calQ^d_\lambda: \calQ^d_\mu)$. Technically, our inductive hypothesis does not cover those $\mu$ for which $\ell(\mu') > r-1$, but for such diagrams, $\Delta^{(d-1,r-1)}_{\lambda-\mu'} = 0$. The identity does too, provided its prefactor is nonnegative. Thus, it suffices to show that
    \begin{equation} \label{eq:almost_almost_there}
        \frac{s_{\lambda^-\cup \mu^-}(1^{r-1})}{s_{\lambda^- \cup \mu^-}(1^{d-1})} \geq  \frac{s_{\lambda^-\cup \mu'}(1^{r-1})}{s_{\lambda^- \cup \mu'}(1^{d-1})}.
    \end{equation}
    To prove this, we note that if $\mu' \preceq \mu$, then $\mu_{i+1} \leq \mu'_{i} \leq \mu_i$ for all $i \in [d-1]$. In particular, $\mu^-_{i} = \mu_{i+1} \leq \mu'_i$ for all $i \in [d-1]$, and hence $\mu^- \subseteq \mu'$. Thus $\lambda^- \cup \mu^- \subseteq \lambda^- \cup \mu'$ for all $\mu'$. \Cref{lem:ratio_of_s's_subset_diagrams} then implies \Cref{eq:almost_almost_there}, and this completes the proof. \qedhere











\end{proof}

