The remainder of the paper is organized as follows.  Section~\ref{sec:preliminaries} introduces the entropic quantities, smoothing conventions, and preliminary results used throughout.  Section~\ref{sec:state-merging} defines the state-merging protocol and states the main theorem.  Section~\ref{sec:converse} proves the converse through the partially smoothed conditional min-entropy.  Section~\ref{sec:achievability} establishes achievability using relative-entropy decoupling, a Log-Euclidean change of measure, controlled recovery, and double pinching.
Section~\ref{sec:conclusion} concludes the paper with a comparison between global and partial smoothing.
Appendix~\ref{app:partial-smoothing-exponent} derives the exact strong converse exponent of the partially smoothed conditional min-entropy.

\section{Entropic quantities and preliminaries}
\label{sec:preliminaries}

\subsection{Notation and basic entropies}

All Hilbert spaces are finite-dimensional, and $\mathbb{N}:=\{1,2,\ldots\}$.  All logarithms are base 2, and for a Hermitian operator $X$ we write $\exp X:=2^X$, defined by functional calculus.  We write $|A|$ for the dimension of a system $A$, $\mathcal{S}(A)$ for the set of states on $A$, and $\mathcal{S}_{\leq}(A)$ for the positive semidefinite operators of trace at most one.  Identity operators and identity tensor factors are suppressed when their systems are clear.  The support of a positive semidefinite operator $X$ is denoted by $\supp(X)$.  Powers and logarithms are evaluated on the relevant support; negative powers denote generalized inverses on that support.  For $p\geq1$, $\norm{X}_p:=(\Tr|X|^p)^{1/p}$.  For a scalar $x$, $[x]_+:=\max\{x,0\}$, whereas for a Hermitian operator $X$, $[X]_+:=(|X|+X)/2$ denotes its positive part.

For isomorphic $K$-dimensional systems $K_A$ and $K_B$ with fixed orthonormal bases, we use
\begin{align}
 |\Phi_K\rangle_{K_AK_B}
 &:=\frac{1}{\sqrt K}\sum_{i=1}^K |i\rangle_{K_A}|i\rangle_{K_B},
 &
 \Phi_{K_AK_B}&:=|\Phi_K\rangle\!\langle\Phi_K|.
 \label{eq:maximally-entangled-state}
\end{align}
The von Neumann entropy is
\begin{align}
 H(A)_\rho:=-\Tr[\rho_A\log\rho_A].
 \label{eq:von-Neumann-entropy}
\end{align}

For $\rho,\sigma\in\mathcal{S}_{\leq}(A)$, the generalized squared fidelity and purified distance are
\begin{align}
 F(\rho,\sigma)
 &:=\left(\norm{\sqrt{\rho}\sqrt{\sigma}}_1
 +\sqrt{(1-\Tr\rho)(1-\Tr\sigma)}\right)^2,
 \label{eq:generalized-fidelity}\\
 P(\rho,\sigma)&:=\sqrt{1-F(\rho,\sigma)}.
 \label{eq:purified-distance}
\end{align}
When both arguments are normalized, $F(\rho,\sigma)$ reduces to the squared Uhlmann fidelity. 
For positive semidefinite operators $X$ and $Y$, we use the homogeneous Umegaki relative entropy
\begin{align}
 D(X\|Y):=
 \begin{cases}
 \Tr\left[X(\log X-\log Y)\right],&\supp(X)\subseteq\supp(Y),\\
 +\infty,&\text{otherwise}
 \end{cases}.
 \label{eq:relative-entropy}
\end{align}
 No trace-correction term such as $-\Tr X+\Tr Y$ is included.  All later uses of $D$ for subnormalized operators, including those in Appendix~\ref{app:partial-smoothing-exponent}, follow this homogeneous convention. 
For a normalized bipartite state, the von Neumann conditional entropy is
\begin{align}
 H(A|B)_\rho
 &:=-D\left(\rho_{AB}\middle\|I_A\otimes\rho_B\right)
 =H(AB)_\rho-H(B)_\rho.
 \label{eq:von-Neumann-conditional-entropy}
\end{align}
The max-relative entropy is
\begin{align}
 D_{\max}(X\|Y):=\inf\{\gamma\in\mathbb{R}:X\leq 2^\gamma Y\}.
 \label{eq:max-relative-entropy}
\end{align}

\subsection{R\'enyi divergences and conditional entropies}

We next collect the R\'enyi quantities used in the exponent formulas.  Whenever a displayed parametrization is indeterminate at an endpoint, its value is understood by the stated continuous extension.

For $\alpha,z>0$ with $\alpha\neq1$, the $\alpha$-$z$ R\'enyi divergence is~\cite{audenaert13_alphaz}
\begin{align}
 D_{\alpha,z}(\rho\|\sigma)
 :=\frac{1}{\alpha-1}\log\Tr\left[
 \left(\rho^{\frac{\alpha}{2z}}
 \sigma^{\frac{1-\alpha}{z}}
 \rho^{\frac{\alpha}{2z}}\right)^z\right],
 \label{eq:alpha-z-divergence}
\end{align}
with the standard support convention.  The sandwiched R\'enyi divergence is $\widetilde D_\alpha=D_{\alpha,\alpha}$~\cite{MDS+13,Wilde3}.
We define the $\alpha$-$z$ conditional R\'enyi entropy
\begin{align}
 H_{\alpha,z}^{\uparrow}(A|B)_\rho
 :=\sup_{\sigma_B\in\mathcal{S}(B)}
 -D_{\alpha,z}\!\left(\rho_{AB}\middle\|I_A\otimes\sigma_B\right).
 \label{eq:alpha-z-conditional}
\end{align}
We also use the fixed-marginal (arrow-down) conditional entropy
\begin{align}
 H_{\alpha,z}^{\downarrow}(A|B)_\rho
 &:=-D_{\alpha,z}\!\left(\rho_{AB}\middle\|I_A\otimes\rho_B\right),
 \label{eq:alpha-z-conditional-down}\\
 \widetilde H_\alpha^{\downarrow}(A|B)_\rho
 &:=H_{\alpha,\alpha}^{\downarrow}(A|B)_\rho.
 \label{eq:sandwiched-conditional-down}
\end{align}
At $\alpha=1$, these quantities are defined by continuity and both equal to $H(A|B)_\rho$.

For $0<\alpha<1$ and $\lambda\leq0$, the club-sandwiched conditional entropy of Ref.~\cite{rubboli2024quantum} is
\begin{align}
 \widetilde H_\alpha^\lambda(A|R)_\rho
 :=\min_{\sigma_R\in\mathcal{S}(R)}\frac{1}{1-\alpha}
 \log\Tr\left[
 \left(
 \rho_{AR}^{1/2}
 \left(I_A\otimes
 \rho_R^{\frac{1-\lambda}{2}\frac{1-\alpha}{\alpha}}
 \sigma_R^{\lambda\frac{1-\alpha}{\alpha}}
 \rho_R^{\frac{1-\lambda}{2}\frac{1-\alpha}{\alpha}}
 \right)
 \rho_{AR}^{1/2}
 \right)^\alpha\right].
 \label{eq:club-entropy}
\end{align}
The objective is set to $+\infty$ unless
$\supp(\rho_{AR})\subseteq\supp(I_A\otimes\sigma_R)$.  With this convention,
negative powers are generalized inverses on the relevant support.  We use the boundary of the data-processing region,
\begin{align}
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho
 =\min_{\sigma_R\in\mathcal{S}(R)}\frac{1}{1-\alpha}
 \log\Tr\left[
 \left(
 \rho_{AR}^{1/2}\rho_R^{1/2}
 \sigma_R^{\frac{1-2\alpha}{\alpha}}
 \rho_R^{1/2}\rho_{AR}^{1/2}
 \right)^\alpha\right].
 \label{eq:club-boundary}
\end{align}
The endpoint values at $\alpha=1/2$ and $\alpha=1$ are defined by the appropriate one-sided limits.  In the parameter range
$\alpha\in[1/2,1)$ and $\frac{1-2\alpha}{1-\alpha}\leq\lambda\leq0$, the club-sandwiched conditional entropy is additive and satisfies data processing under channels on the conditioning system~\cite[Theorems~4.1 and~5.1]{rubboli2024quantum}.  Moreover,
\begin{align}
 \lim_{\alpha\nearrow1}
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho
 &=H(A|R)_\rho,
 \label{eq:club-limit}\\
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho
 &\geq H(A|R)_\rho,
 \qquad \alpha\in[1/2,1].
 \label{eq:club-lower-bound}
\end{align}
These properties are proved in Ref.~\cite[Lemmas~17 and~18]{rubboli2026strong}.

For a normalized state $\eta$, a positive semidefinite operator $\sigma$, and $0<\alpha<1$, the Log-Euclidean R\'enyi divergence is~\cite{audenaert13_alphaz,mosonyi2017strong}
\begin{align}
 D_{\alpha,\infty}(\eta\|\sigma)
 :=\frac{1}{\alpha-1}\log\Tr\left[
 Q\exp\left(Q(\alpha\log\eta+(1-\alpha)\log\sigma)Q\right)\right],
 \label{eq:LE-divergence}
\end{align}
where $Q$ projects onto $\supp(\eta)\cap\supp(\sigma)$.  Its Gibbs variational representation, obtained from the variational formula for quantum relative entropy~\cite{petz1988variational} (see also the use of this representation in Refs.~\cite{mosonyi2017strong,rubboli2026strong}), is
\begin{align}
 D_{\alpha,\infty}(\eta\|\sigma)
 =\frac{1}{1-\alpha}\min_{\substack{\tau\in\mathcal{S}\\
 \supp(\tau)\subseteq\supp(\eta)\cap\supp(\sigma)}}
 \left\{\alpha D(\tau\|\eta)+(1-\alpha)D(\tau\|\sigma)\right\}.
 \label{eq:LE-Gibbs}
\end{align}
At $\alpha=1/2$, the Araki--Lieb--Thirring inequality~\cite{araki1990inequality} gives
\begin{align}
 -\log F(\eta,\sigma)=\widetilde D_{1/2}(\eta\|\sigma)
 \leq D_{1/2,\infty}(\eta\|\sigma).
 \label{eq:fidelity-LE}
\end{align}
The formulas above remain valid when $\sigma$ is subnormalized.  

For $0<\alpha<1$ and $\lambda\leq0$, the associated conditional entropy is
\begin{align}
 H_{\alpha,\infty}^{\lambda}(A|R)_\rho
 &:=\min_{\sigma_R\in\mathcal{S}(R)}\frac{1}{1-\alpha}
 \log\Tr\Big[Q_\rho\exp\Big(
 \alpha\log\rho_{AR}
+(1-\alpha)Q_\rho
 \big((1-\lambda)\log\rho_R+\lambda\log\sigma_R\big)Q_\rho
 \Big)\Big],
 \label{eq:LE-conditional}
\end{align}
where $Q_\rho$ projects onto $\supp(\rho_{AR})$ and identities on $A$ are omitted inside the logarithm.
The objective is set to $+\infty$ unless
$\supp(\rho_{AR})\subseteq\supp(I_A\otimes\sigma_R)$, and logarithms are evaluated on the corresponding supports.

\subsection{Smoothing and auxiliary results}

The smoothing quantities and auxiliary one-shot tools below connect the entropic formulas to state merging.  A quantum instrument is a finite family of completely positive, trace-nonincreasing maps whose sum is trace preserving.  We say that it has \emph{one Kraus operator per outcome} when every outcome map has Kraus rank one.

The globally smoothed conditional min-entropy with the conditioning operator fixed to $\rho_R$ is~\cite{anshu2020partially}
\begin{align}
 H_{\min}^{\varepsilon,P}(A|R)_\rho
 :=\max_{\substack{\tau_{AR}\in\mathcal{S}_{\leq}(AR)\\
 P(\tau_{AR},\rho_{AR})\leq\varepsilon}}
 \left[-D_{\max}\!\left(\tau_{AR}\middle\|I_A\otimes\rho_R\right)\right].
 \label{eq:globally-smoothed-min}
\end{align}
The partially smoothed conditional min-entropy that enters the merging converse also imposes the marginal constraint $\tau_R\leq\rho_R$:
\begin{align}
 H_{\min}^{\varepsilon,P}(A|\dot R)_\rho
 :=\max_{\substack{\tau_{AR}\in\mathcal{S}_{\leq}(AR)\\
 P(\tau_{AR},\rho_{AR})\leq\varepsilon,\;\tau_R\leq\rho_R}}
 \left[-D_{\max}\!\left(\tau_{AR}\middle\|I_A\otimes\rho_R\right)\right].
 \label{eq:partially-smoothed-min}
\end{align}

\begin{proposition}[Partially smoothed one-way merging converse {\cite{anshu2020partially}}]
\label{prop:partially-smoothed-converse}
Let $\psi_{ABR}$ be pure.  If a one-way merging protocol has purified-distance error at most $\varepsilon\in(0,1]$, initial and final Schmidt ranks $K$ and $L$, and net entanglement cost $c=\log K-\log L$, then
\begin{align}
 c\geq-H_{\min}^{\varepsilon,P}(A|\dot R)_\psi.
 \label{eq:partially-smoothed-converse}
\end{align}
\end{proposition}

Proposition~\ref{prop:partially-smoothed-converse} is the converse part of Theorem~6 of Ref.~\cite{anshu2020partially}, translated to the squared-fidelity convention in \eqref{eq:generalized-fidelity}.

\begin{proposition}[Fixed-output relative-entropy decoupling {\cite{berta2026tight}}]
\label{prop:fixed-output-decoupling}
Let $\tau_{AR}\in\mathcal{S}(AR)$ and $q<H(A|R)_\tau$.  There exist finite-dimensional registers $K_{A,n}$ and $L_{A,n}$, a finite classical register $J_n$, and a one-Kraus-per-outcome instrument
$\mathcal{A}_n:A^nK_{A,n}\to J_nL_{A,n}$, such that
\begin{align}
 \log|L_{A,n}|-\log|K_{A,n}|&\geq nq,
 \label{eq:decoupling-gain}\\
 \frac{1}{n}\left(\log|L_{A,n}|-\log|K_{A,n}|\right)&\longrightarrow q,
 \label{eq:decoupling-gain-limit}
\end{align}
and, for a constant $c=c(\tau,q)>0$ independent of $n$ and all sufficiently large $n$,
\begin{align}
 D\!\left(
 (\mathcal{A}_n\otimes\mathrm{id}_{R^n})
 (\tau_{AR}^{\otimes n}\otimes\pi_{K_{A,n}})
 \middle\|
 \pi_{J_n}\otimes\pi_{L_{A,n}}\otimes\tau_R^{\otimes n}
 \right)
 \leq2^{-cn}.
 \label{eq:fixed-output-decoupling}
\end{align}
The statement permits both isometric padding of $A^nK_{A,n}$ and an isometric embedding of the physical output into $L_{A,n}$.
\end{proposition}

This is the equal-rank partial-isometry specialization of Lemma~9 and the construction in the proof of Theorem~10 of Ref.~\cite{berta2026tight}.  We use Proposition~\ref{prop:fixed-output-decoupling} as an existing decoupling theorem and do not reproduce its proof.

\begin{proposition}[Log-Euclidean conditional variational formula {\cite{rubboli2026strong}}]
\label{prop:LE-conditional-variational}
For every $\rho_{AR}\in\mathcal{S}(AR)$, $0<\alpha<1$, and $\lambda\leq0$,
\begin{align}
 (\alpha-1)H_{\alpha,\infty}^{\lambda}(A|R)_\rho
 &=\min_{\tau_{AR}\in\mathcal{S}(AR)}\Big\{
 (1-\lambda)(1-\alpha)D(\tau_R\|\rho_R)
+\alpha D(\tau_{AR}\|\rho_{AR})
 +(\alpha-1)H(A|R)_\tau\Big\}.
 \label{eq:LE-conditional-variational}
\end{align}
\end{proposition}

Proposition~\ref{prop:LE-conditional-variational} is Lemma~7 of Ref.~\cite{rubboli2026strong}; its statement is valid for every bipartite quantum state.

\begin{proposition}[Club-sandwiched duality {\cite{rubboli2024quantum,rubboli2026strong}}]
\label{prop:club-duality}
Let $\psi_{ABR}$ be pure.  For $\alpha\in[1/2,1]$, with endpoint values defined by continuity,
\begin{align}
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\psi
 =-H_{\frac{2\alpha}{3\alpha-1},\frac{\alpha}{3\alpha-1}}^{\uparrow}(A|B)_\psi.
 \label{eq:club-duality}
\end{align}
\end{proposition}

This is the duality relation used in Lemma~16 of Ref.~\cite{rubboli2026strong}; it is a specialization of the general duality theory in Ref.~\cite{rubboli2024quantum}.

For a positive semidefinite operator $X=\sum_i x_iP_i$ with distinct eigenvalues $x_i$, let
\begin{align}
 \P_X(Y):=\sum_iP_iYP_i
 \label{eq:pinching-map}
\end{align}
be the pinching with respect to $X$.  We write $|\operatorname{spec}(X)|$ for the number of distinct eigenvalues of $X$.

\begin{proposition}[Universal state and symmetric optimizer {\cite{hayashitomamichel15c,rubboli2026strong}}]
\label{prop:universal-state}
Let $R$ have dimension $d_R$.  For every $m\in\mathbb{N}$, there exists a permutation-invariant universal state $\omega_{R^m}$ such that every permutation-invariant state $\sigma_{R^m}$ satisfies
\begin{align}
 \sigma_{R^m}\leq(m+1)^{d_R^2-1}\omega_{R^m}.
 \label{eq:universal-domination}
\end{align}
Moreover, $\omega_{R^m}$ commutes with every permutation-invariant state, and
\begin{align}
 \max\left\{
 |\operatorname{spec}(\rho_R^{\otimes m})|,
 |\operatorname{spec}(\omega_{R^m})|
 \right\}\leq(m+1)^{d_R-1}.
 \label{eq:spectral-cardinality}
\end{align}
If a bipartite state on $A^mR^m$ is invariant under simultaneous permutations of the $m$ copies, then for every $0<\alpha<1$ and $\lambda\leq0$, an optimizer in \eqref{eq:LE-conditional} can be chosen permutation-invariant on $R^m$. 
\end{proposition}

The universal-state properties are collected in Lemma~26 of Ref.~\cite{rubboli2026strong}, and the optimizer symmetry is Lemma~20 in the same reference.

\begin{proposition}[Fidelity loss under pinching {\cite{tomamichel16_book,rubboli2026strong}}]
\label{prop:fidelity-pinching}
Let $\P(Y)=\sum_{i=1}^vP_iYP_i$ be a pinching with $v$ spectral projections.  If $\eta\in\mathcal{S}$, $\sigma\in\mathcal{S}_{\leq}$, and $\P(\sigma)=\sigma$, then
\begin{align}
 -\log F(\eta,\sigma)
 \leq-\log F(\P(\eta),\sigma)+\log v.
 \label{eq:fidelity-pinching}
\end{align}
\end{proposition}

This is the $\alpha=1/2$ pinching estimate used as Lemma~27 of Ref.~\cite{rubboli2026strong}; see also Lemma~4.11 of Ref.~\cite{tomamichel16_book}.  The same proof applies when the second argument is subnormalized, because the first argument is normalized.

\section{Quantum state merging and the strong converse exponent}
\label{sec:state-merging}

Let $\psi_{ABR}$ be pure, where Alice holds $A$, Bob holds $B$, and $R$ is an inaccessible reference system.  A blocklength-$n$ \emph{one-way quantum state-merging protocol} consists of an initially shared maximally entangled state $\Phi_{K_{A,n}K_{B,n}}$ with $|K_{A,n}|=|K_{B,n}|=K_n$, an instrument $\{\mathcal{E}_{x,n}:A^nK_{A,n}\to L_{A,n}\}_x$ applied by Alice, transmission of the outcome $x$ to Bob, and a channel $\mathcal{D}_{x,n}:B^nK_{B,n}\to\widehat A^nB^nL_{B,n}$ applied by Bob.  Here, $\widehat A$ is an isomorphic copy of $A$ held by Bob.  The output state is
\begin{align}
 \omega^{\mathcal{M}_n}_{L_{A,n}L_{B,n}\widehat A^nB^nR^n}
 :=\sum_x
 (\mathcal{E}_{x,n}\otimes\mathcal{D}_{x,n}\otimes\mathrm{id}_{R^n})
 \left(\psi_{ABR}^{\otimes n}\otimes\Phi_{K_{A,n}K_{B,n}}\right).
 \label{eq:merging-output}
\end{align}
The ideal output is
\begin{align}
 \Phi_{L_{A,n}L_{B,n}}\otimes\psi_{\widehat A BR}^{\otimes n},
 \label{eq:merging-target}
\end{align}
where $|L_{A,n}|=|L_{B,n}|=L_n$ and $\Phi_{L_{A,n}L_{B,n}}$ has Schmidt rank $L_n$.  This is the usual state-merging task introduced and developed in Refs.~\cite{horodecki2005partial,horodecki2007merging}, with arbitrary forward classical communication.

The net entanglement cost of $\mathcal{M}_n$ is
\begin{align}
 c(\mathcal{M}_n):=\log K_n-\log L_n.
 \label{eq:net-entanglement-cost}
\end{align}
Only this difference is constrained; no separate upper bound is imposed on $K_n$ or $L_n$.  For $r\in\mathbb{R}$, define the optimal squared fidelity
\begin{align}
 F_n^{\mathrm{merg}}(\psi,r)
 :=\sup_{\substack{\mathcal{M}_n:\;c(\mathcal{M}_n)\leq nr}}
 F\!\left(
 \omega^{\mathcal{M}_n},
 \Phi_{L_{A,n}L_{B,n}}\otimes\psi_{\widehat A BR}^{\otimes n}
 \right),
 \label{eq:optimal-merging-fidelity}
\end{align}
where the supremum ranges over all finite choices of $K_n$ and $L_n$ and all protocols of the form above.

\begin{theorem}[Exact strong converse exponent]
\label{thm:main}
For every finite-dimensional pure state $\psi_{ABR}$ and every $r\in\mathbb{R}$, the limit
\begin{align}
 E_{\mathrm{sc}}^{\mathrm{merg}}(\psi,r)
 :=\lim_{n\to\infty}-\frac{1}{n}\log F_n^{\mathrm{merg}}(\psi,r)
 \label{eq:strong-converse-exponent-definition}
\end{align}
exists and satisfies
\begin{align}
 \boxed{
  E_{\mathrm{sc}}^{\mathrm{merg}}(\psi,r)
 =\max_{\alpha\in[1,2]}\frac{2(\alpha-1)}{\alpha}
 \left[H_{\alpha,\alpha/2}^{\uparrow}(A|B)_\psi-r\right]
 }
 \label{eq:main-conditional-entropy}
\end{align}
Moreover,
\begin{align}
 E_{\mathrm{sc}}^{\mathrm{merg}}(\psi,r)>0
 \quad\Longleftrightarrow\quad
 r<H(A|B)_\psi.
 \label{eq:positive-region}
\end{align}
\end{theorem}

\noindent The converse direction ($\geq$) in \eqref{eq:main-conditional-entropy} is proved in Section~\ref{sec:converse}, and the achievability direction ($\leq$) is proved in Section~\ref{sec:achievability}.

Writing $q:=-r$ for the net entanglement-distillation rate, the club-sandwiched conditional entropy duality in Proposition~\ref{prop:club-duality} gives the equivalent representation
\begin{align}
 E_{\mathrm{sc}}^{\mathrm{merg}}(\psi,r)
 =\max_{\alpha\in[1/2,1]}\frac{1-\alpha}{\alpha}
 \left[q-
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\psi\right].
 \label{eq:main-club-form}
\end{align}
The positivity of the strong converse exponent is then
\begin{align}
 E_{\mathrm{sc}}^{\mathrm{merg}}(\psi,r)>0
 \quad\Longleftrightarrow\quad
 q> \lim_{\alpha\nearrow1}  \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\psi =  H(A|R)_\psi,
 \label{eq:positive-region-club}
\end{align}
where purity gives $H(A|B)_\psi=-H(A|R)_\psi$.

\section{Converse}
\label{sec:converse}

For $\rho_{AR}\in\mathcal{S}(AR)$ and $q\in\mathbb{R}$, define the fixed-marginal smoothing fidelity
\begin{align}
 \Gamma_{A|\dot R}(\rho,q)
 :=\max_{\substack{\tau_{AR}\in\mathcal{S}_{\leq}(AR)\\
 \tau_R\leq\rho_R,\;\tau_{AR}\leq2^{-q}I_A\otimes\rho_R}}
 F(\rho_{AR},\tau_{AR}).
 \label{eq:Gamma-definition}
\end{align}
The maximum exists by compactness.  By \eqref{eq:partially-smoothed-min} and $P(\rho,\tau)^2=1-F(\rho,\tau)$, for every $\varepsilon\in[0,1]$,
\begin{align}
 H_{\min}^{\varepsilon,P}(A|\dot R)_\rho\geq q
 \quad\Longleftrightarrow\quad
 \Gamma_{A|\dot R}(\rho,q)\geq1-\varepsilon^2.
 \label{eq:Hmin-Gamma-equivalence}
\end{align}

\begin{lemma}[One-shot strong converse for partially smoothed conditional min-entropy]
\label{lem:partial-smoothing-one-shot}
For every $\rho_{AR}\in\mathcal{S}(AR)$, $q\in\mathbb{R}$, and $\alpha\in[1/2,1)$,
\begin{align}
 \Gamma_{A|\dot R}(\rho,q)
 \leq
 2^{-\frac{1-\alpha}{\alpha}
 \left[q-\widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho\right]}.
 \label{eq:Gamma-one-shot-converse}
\end{align}
Equivalently, if $H_{\min}^{\varepsilon,P}(A|\dot R)_\rho\geq q$, then
\begin{align}
 1-\varepsilon^2
 \leq
 2^{-\frac{1-\alpha}{\alpha}
 \left[q-\widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho\right]}.
 \label{eq:Hmin-one-shot-converse}
\end{align}
\end{lemma}

\begin{proof}
Restrict $R$ to $\supp(\rho_R)$ and fix an operator $\tau_{AR}$ feasible in \eqref{eq:Gamma-definition}.  Fix $\alpha\in(1/2,1)$ and a faithful $\sigma_R$.  The following noncommutative H\"older inequality is the fully quantum analogue of the factorization used for the club-sandwiched converse in Ref.~\cite{rubboli2026strong}; we use the Schatten-norm H\"older inequality in the form recorded, for example, in Ref.~\cite{bhatia1997matrix}:
\begin{align}
 \sqrt{F(\rho_{AR},\tau_{AR})}
 &\leq
 \norm{\rho_{AR}^{1/2}
 \left(I_A\otimes\rho_R^{1/2}
 \sigma_R^{\frac{1-2\alpha}{2\alpha}}\right)}_{2\alpha}

 \times
 \norm{\left(I_A\otimes
 \sigma_R^{\frac{2\alpha-1}{2\alpha}}\rho_R^{-1/2}\right)
 \tau_{AR}^{1/2}}_{\frac{2\alpha}{2\alpha-1}}.
 \label{eq:Gamma-holder-factorization}
\end{align}
The square of the first factor equals
\begin{align}
 \left\{\Tr\left[
 \left(
 \rho_{AR}^{1/2}\rho_R^{1/2}
 \sigma_R^{\frac{1-2\alpha}{\alpha}}
 \rho_R^{1/2}\rho_{AR}^{1/2}
 \right)^\alpha\right]\right\}^{1/\alpha}.
 \label{eq:Gamma-first-holder-factor}
\end{align}
For the second factor, set
\begin{align}
 C_{AR}:=(I_A\otimes\rho_R^{-1/2})
 \tau_{AR}(I_A\otimes\rho_R^{-1/2}).
 \label{eq:Gamma-C-definition}
\end{align}
The two constraints in \eqref{eq:Gamma-definition} imply
\begin{align}
 0\leq C_{AR}\leq2^{-q}I_{AR},
 \qquad
 \Tr[(I_A\otimes\sigma_R)C_{AR}]\leq1.
 \label{eq:Gamma-C-bounds}
\end{align}
The Araki--Lieb--Thirring inequality~\cite{araki1990inequality} therefore yields
\begin{align}
\norm{\left(I_A\otimes
 \sigma_R^{\frac{2\alpha-1}{2\alpha}}\rho_R^{-1/2}\right)
 \tau_{AR}^{1/2}}_{\frac{2\alpha}{2\alpha-1}}^{\frac{2\alpha}{2\alpha-1}}
&\leq
 \Tr\left[(I_A\otimes\sigma_R^{1/2})
 C_{AR}^{\frac{\alpha}{2\alpha-1}}
 (I_A\otimes\sigma_R^{1/2})\right]
 \nonumber\\
 &\leq
 2^{-q\frac{1-\alpha}{2\alpha-1}}
 \Tr[(I_A\otimes\sigma_R)C_{AR}]
 \leq2^{-q\frac{1-\alpha}{2\alpha-1}}.
 \label{eq:Gamma-second-holder-factor}
\end{align}
Thus the square of the second factor in \eqref{eq:Gamma-holder-factorization} is at most $2^{-q(1-\alpha)/\alpha}$.  Combining this with \eqref{eq:Gamma-first-holder-factor}, minimizing over $\sigma_R$, and using \eqref{eq:club-boundary} proves \eqref{eq:Gamma-one-shot-converse} for $\alpha\in(1/2,1)$.  The bound for singular $\sigma_R$ follows by full-rank regularization, and the endpoint $\alpha=1/2$ follows by one-sided continuity.  Equation \eqref{eq:Hmin-one-shot-converse} is then immediate from \eqref{eq:Hmin-Gamma-equivalence}.
\end{proof}

\begin{lemma}[One-shot operational reduction]
\label{lem:one-shot-operational-reduction}
Let a state-merging protocol for $\psi_{ABR}$ have initial and final Schmidt ranks $K$ and $L$, coherent entanglement gain
\begin{align}
 q:=\log L-\log K,
 \label{eq:coherent-gain}
\end{align}
and squared fidelity $f$.  Then
\begin{align}
 f\leq\Gamma_{A|\dot R}(\psi_{AR},q).
 \label{eq:operational-Gamma-reduction}
\end{align}
\end{lemma}

\begin{proof}
The claim is trivial when $f=0$.  If $0<f<1$, the purified-distance error is $\varepsilon=\sqrt{1-f}$.  Proposition~\ref{prop:partially-smoothed-converse} gives
\begin{align}
 H_{\min}^{\varepsilon,P}(A|\dot R)_\psi\geq q,
 \label{eq:operational-Hmin-lower-bound}
\end{align}
and \eqref{eq:Hmin-Gamma-equivalence} yields \eqref{eq:operational-Gamma-reduction}.  If $f=1$, the same conclusion follows by applying the argument with any $\varepsilon>0$ and letting $\varepsilon\downarrow0$.
\end{proof}

\begin{theorem}[Finite-block converse and exponent lower bound]
\label{thm:converse}
For every pure state $\psi_{ABR}$, every $r\in\mathbb{R}$, every $n\in\mathbb{N}$, and every $\alpha\in[1,2]$,
\begin{align}
 F_n^{\mathrm{merg}}(\psi,r)
 \leq 2^{-n \frac{2(\alpha-1)}{\alpha}
 \left[H_{\alpha,\alpha/2}^{\uparrow}(A|B)_\psi-r\right]}.
 \label{eq:finite-block-converse}
\end{align}
Consequently,
\begin{align}
 \liminf_{n\to\infty}-\frac{1}{n}\log F_n^{\mathrm{merg}}(\psi,r)
 \geq
 \max_{\alpha\in[1,2]}\frac{2(\alpha-1)}{\alpha}
 \left[H_{\alpha,\alpha/2}^{\uparrow}(A|B)_\psi-r\right].
 \label{eq:converse-exponent}
\end{align}
\end{theorem}

\begin{proof}
Fix $n\in\mathbb{N}$, $\alpha\in[1/2,1)$, and an admissible protocol.  Its coherent gain satisfies
\begin{align}
 \log L_n-\log K_n\geq-nr.
 \label{eq:gain-rate-constraint}
\end{align}
Combining Lemmas~\ref{lem:one-shot-operational-reduction} and~\ref{lem:partial-smoothing-one-shot} with additivity of the club-sandwiched conditional entropy gives
\begin{align}
 F\!\left(
 \omega^{\mathcal{M}_n},
 \Phi_{L_{A,n}L_{B,n}}\otimes\psi_{\widehat A BR}^{\otimes n}
 \right)
 \leq
 2^{-n\frac{1-\alpha}{\alpha}
 \left[-r-
 \widetilde H_\alpha^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\psi\right]}.
 \label{eq:uniform-converse}
\end{align}
The right-hand side is independent of the protocol, so the same bound holds for $F_n^{\mathrm{merg}}(\psi,r)$.  Set
\begin{align}
 \beta:=\frac{2\alpha}{3\alpha-1}.
 \label{eq:parameter-conversion}
\end{align}
As $\alpha$ ranges from $1/2$ to $1$, $\beta$ ranges from $2$ to $1$, and $(1-\alpha)/\alpha=2(\beta-1)/\beta$.  Proposition~\ref{prop:club-duality} therefore converts the protocol-independent one-shot bound into \eqref{eq:finite-block-converse} for $\beta\in(1,2]$.  At $\beta=1$, Eq.~\eqref{eq:finite-block-converse} reduces to the trivial estimate $F_n^{\mathrm{merg}}(\psi,r)\leq1$ and is included by continuity.  Taking negative logarithms, dividing by $n$, taking the liminf, and then optimizing over $\beta\in[1,2]$ yields \eqref{eq:converse-exponent}.
Since $\beta\in[1,2]$ is only a dummy variable, we write $\alpha\in[1,2]$ by convention
\end{proof}

\section{Achievability}
\label{sec:achievability}

The proof reduces the problem to fixed-output decoupling.  Relative-entropy decoupling enters through Proposition~\ref{prop:fixed-output-decoupling}.  We first obtain a Log-Euclidean exponent by a change of measure, then convert fixed-output fidelity into merging fidelity by a controlled Uhlmann argument, and finally use double pinching to replace the Log-Euclidean entropy by the club-sandwiched entropy.

\subsection{Log-Euclidean fixed-output exponent}

\begin{lemma}[Variational identity]
\label{lem:LE-exponent-variational}
For every $\rho_{AR}\in\mathcal{S}(AR)$ and every $q\in\mathbb{R}$,
\begin{align}
 &\max_{\alpha\in[1/2,1]}
 \frac{1-\alpha}{\alpha}
 \left[q-H_{\alpha,\infty}^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho\right]
 \nonumber\\
 &\qquad=
 \min_{\tau_{AR}\in\mathcal{S}(AR)}
 \left\{
 D(\tau_{AR}\|\rho_{AR})+D(\tau_R\|\rho_R)
 +[q-H(A|R)_\tau]_+
 \right\}.
 \label{eq:LE-exponent-variational}
\end{align}
\end{lemma}

\begin{proof}
Apply Proposition~\ref{prop:LE-conditional-variational} with
$\lambda=(1-2\alpha)/(1-\alpha)$.  Since
\begin{align}
 (1-\lambda)(1-\alpha)=\alpha,
 \label{eq:LE-path-identity}
\end{align}
setting $t=(1-\alpha)/\alpha$ gives
\begin{align}
 \max_{0\leq t\leq1}\min_{\tau_{AR}\in\mathcal{S}(\supp\rho_{AR})}
 \Bigl\{
 D(\tau_{AR}\|\rho_{AR})+D(\tau_R\|\rho_R)
 +t\bigl(q-H(A|R)_\tau\bigr)
 \Bigr\}.
 \label{eq:LE-minimax}
\end{align}
Here $\mathcal{S}(\supp\rho_{AR})$ denotes the states supported on $\supp(\rho_{AR})$; states outside this set have infinite objective.  The endpoint $\alpha=1$ is represented by $t=0$ through continuous extension.  The state space is compact and convex.  For fixed $t$, the objective is convex and continuous in $\tau_{AR}$ on this support-restricted domain, and for fixed $\tau_{AR}$ it is affine and continuous in $t$.  Sion's minimax theorem~\cite{sion1958general} therefore yields
\begin{align}
 \min_{\tau_{AR}\in\mathcal{S}(\supp\rho_{AR})}
 \Bigl\{
 D(\tau_{AR}\|\rho_{AR})+D(\tau_R\|\rho_R)
 +\max_{0\leq t\leq1}t\bigl(q-H(A|R)_\tau\bigr)
 \Bigr\}.
 \label{eq:LE-minimax-exchanged}
\end{align}
Finally,
\begin{align}
 \max_{0\leq t\leq1}t\bigl(q-H(A|R)_\tau\bigr)
 =[q-H(A|R)_\tau]_+,
 \label{eq:positive-part-identity}
\end{align}
which proves the claim.
\end{proof}

\begin{proposition}[Log-Euclidean fixed-output achievability]
\label{prop:LE-fixed-output}
For every $\rho_{AR}\in\mathcal{S}(AR)$ and $q\in\mathbb{R}$, there exist one-Kraus-per-outcome instruments $\mathcal{A}_n:A^nK_{A,n}\to J_nL_{A,n}$ such that
\begin{align}
 \log|L_{A,n}|-\log|K_{A,n}|&\geq nq,
 \label{eq:LE-achievable-gain}\\
 \frac{1}{n}\left(\log|L_{A,n}|-\log|K_{A,n}|\right)&\longrightarrow q,
 \label{eq:LE-achievable-gain-limit}
\end{align}
and, with
\begin{align}
 \omega_n^\rho
 &:=(\mathcal{A}_n\otimes\mathrm{id}_{R^n})
 (\rho_{AR}^{\otimes n}\otimes\pi_{K_{A,n}}),
 \label{eq:omega-rho}\\
 \zeta_n^\rho
 &:=\pi_{J_n}\otimes\pi_{L_{A,n}}\otimes\rho_R^{\otimes n},
 \label{eq:zeta-rho}
\end{align}
we have
\begin{align}
 \limsup_{n\to\infty}-\frac{1}{n}\log F(\omega_n^\rho,\zeta_n^\rho)
 \leq
 \max_{\alpha\in[1/2,1]}
 \frac{1-\alpha}{\alpha}
 \left[q-H_{\alpha,\infty}^{\frac{1-2\alpha}{1-\alpha}}(A|R)_\rho\right].
 \label{eq:LE-fixed-output-achievability}
\end{align}
\end{proposition}

\begin{proof}
	Choose a minimizer $\tau_{AR}$ in \eqref{eq:LE-exponent-variational}, which exists by compactness and lower semicontinuity.

	Suppose first that $q<H(A|R)_\tau$.  Apply Proposition~\ref{prop:fixed-output-decoupling} to $\tau_{AR}$ at coherent gain $q$, and then apply the resulting instrument to $\rho_{AR}^{\otimes n}\otimes\pi_{K_{A,n}}$.  Denote
	\begin{align}
		\omega_n^\tau
		&:=(\mathcal{A}_n\otimes\mathrm{id}_{R^n})
		(\tau_{AR}^{\otimes n}\otimes\pi_{K_{A,n}}),
		&
		\zeta_n^\tau
		&:=\pi_{J_n}\otimes\pi_{L_{A,n}}\otimes\tau_R^{\otimes n}.
		\label{eq:tau-output-and-target}
	\end{align}
	Using \eqref{eq:fidelity-LE} and evaluating the variational formula \eqref{eq:LE-Gibbs} at $\omega_n^\tau$, we obtain
	\begin{align}
		-\log F(\omega_n^\rho,\zeta_n^\rho)
		&\leq D_{1/2,\infty}(\omega_n^\rho\|\zeta_n^\rho)
		\nonumber\\
		&\leq D(\omega_n^\tau\|\omega_n^\rho)
		+D(\omega_n^\tau\|\zeta_n^\rho).
		\label{eq:change-of-measure}
	\end{align}
	Data processing gives
	\begin{align}
		D(\omega_n^\tau\|\omega_n^\rho)
		\leq nD(\tau_{AR}\|\rho_{AR}).
		\label{eq:first-change-of-measure-term}
	\end{align}
	Moreover, $(\omega_n^\tau)_{R^n}=\tau_R^{\otimes n}$, and therefore
	\begin{align}
		D(\omega_n^\tau\|\zeta_n^\rho)
		=D(\omega_n^\tau\|\zeta_n^\tau)
		+nD(\tau_R\|\rho_R).
		\label{eq:fixed-target-chain-rule}
	\end{align}
	The first term on the right of \eqref{eq:fixed-target-chain-rule} converges to zero exponentially by Proposition~\ref{prop:fixed-output-decoupling}.  Hence
	\begin{align}
		\limsup_{n\to\infty}-\frac{1}{n}\log F(\omega_n^\rho,\zeta_n^\rho)
		\leq D(\tau_{AR}\|\rho_{AR})+D(\tau_R\|\rho_R).
		\label{eq:LE-low-gain}
	\end{align}

	Suppose now that $q\geq H(A|R)_\tau$.  Choose numbers $\delta_j\downarrow0$.  For each $j$, apply the preceding argument at gain $H(A|R)_\tau-\delta_j$.  By Proposition~\ref{prop:fixed-output-decoupling}, there is an integer $N_j$ such that, for every $n\geq N_j$, the corresponding decoupling estimate holds and the physical coherent gain $g_{n,j}:=n^{-1}(\log L'_{n,j}-\log K_{n,j})$ satisfies
	\begin{align}
		\left|g_{n,j}-\bigl(H(A|R)_\tau-\delta_j\bigr)\right|\leq\delta_j.
		\label{eq:diagonal-gain-control}
	\end{align}
	Take the $N_j$ strictly increasing.  For $n\geq N_1$, set $j(n):=\max\{j:N_j\leq n\}$ and $\delta_n:=\delta_{j(n)}$; for the finitely many $n<N_1$, choose any admissible instrument and set $\delta_n:=\delta_1$.  Then $\delta_n\to0$, and for every $n\geq N_1$ the instrument from the $j(n)$th family satisfies both the decoupling estimate and \eqref{eq:diagonal-gain-control}.  Using the harmless common input--output padding allowed in Proposition~\ref{prop:fixed-output-decoupling}, we may also arrange that integer rounding contributes $o(n)$ to all logarithmic dimensions.

	Keep the same initial entanglement rank and isometrically embed the physical output of dimension $L_n':=L'_{n,j(n)}$ into a declared system of dimension
	\begin{align}
		L_n:=\left\lceil |K_{A,n}|2^{nq}\right\rceil.
		\label{eq:declared-output-dimension}
	\end{align}
	For all sufficiently large $n$, $L_n\geq L_n'$.  Let $\omega_{n,\mathrm{phys}}^\rho$ denote the source output on $J_nL'_{A,n}R^n$, and set $\zeta_{n,\mathrm{phys}}^\rho:=\pi_{J_n}\otimes\pi_{L_n'}\otimes\rho_R^{\otimes n}$.  Let $\iota_n:L_{A,n}'\hookrightarrow L_{A,n}$ be an isometric embedding and compose the physical instrument with $\mathrm{id}_{J_n}\otimes\iota_n$.  The resulting declared output and target are
	\begin{align}
		\omega_n^\rho
		&:= (\mathrm{id}_{J_n}\otimes\iota_n\otimes\mathrm{id}_{R^n})
		\omega_{n,\mathrm{phys}}^\rho
		(\mathrm{id}_{J_n}\otimes\iota_n^\dagger\otimes\mathrm{id}_{R^n}),
		&
		\zeta_n^\rho
		&:=\pi_{J_n}\otimes\pi_{L_n}\otimes\rho_R^{\otimes n}.
		\label{eq:declared-embedded-output}
	\end{align}
	Since $\omega_n^\rho$ remains supported on the embedded $L_n'$-dimensional subspace, squared fidelity satisfies
	\begin{align}
		F(\omega_n^\rho,\zeta_n^\rho)
		&=\frac{L_n'}{L_n}
		F(\omega_{n,\mathrm{phys}}^\rho,\zeta_{n,\mathrm{phys}}^\rho).
		\label{eq:fidelity-embedding-scaling}
	\end{align}
	The declared gain is at least $q$ and converges to $q$, while \eqref{eq:diagonal-gain-control} gives
	\begin{align}
		\limsup_{n\to\infty}\frac{1}{n}\log\frac{L_n}{L_n'}
		\leq q-H(A|R)_\tau.
		\label{eq:diagonal-embedding-penalty}
	\end{align}
	Consequently,
	\begin{align}
		\limsup_{n\to\infty}-\frac{1}{n}\log F(\omega_n^\rho,\zeta_n^\rho)
		\leq D(\tau_{AR}\|\rho_{AR})+D(\tau_R\|\rho_R)
		+q-H(A|R)_\tau.
		\label{eq:LE-high-gain}
	\end{align}
	In each regime, the corresponding right-hand side in \eqref{eq:LE-low-gain} or \eqref{eq:LE-high-gain} equals the objective in \eqref{eq:LE-exponent-variational} evaluated at the chosen minimizer.  This proves \eqref{eq:LE-fixed-output-achievability}, while the dimension choices give \eqref{eq:LE-achievable-gain} and \eqref{eq:LE-achievable-gain-limit}.
\end{proof}

\subsection{Controlled Uhlmann recovery}

\begin{lemma}[Controlled Uhlmann recovery]
\label{lem:controlled-Uhlmann}
Let $\mathcal{A}:A^nK_A\to JL_A$ be a one-Kraus-per-outcome instrument applied to
$\psi_{ABR}^{\otimes n}\otimes\Phi_{K_AK_B}$, and define
\begin{align}
 \omega_{JL_AR^n}
 &:=(\mathcal{A}\otimes\mathrm{id}_{R^n})
 (\psi_{AR}^{\otimes n}\otimes\pi_{K_A}),
 \label{eq:controlled-Uhlmann-output}\\
 \zeta_{JL_AR^n}
 &:=\pi_J\otimes\pi_{L_A}\otimes\psi_R^{\otimes n}.
 \label{eq:controlled-Uhlmann-target}
\end{align}
There exist outcome-dependent recovery isometries for Bob that produce a state-merging protocol whose initial and final Schmidt ranks are $|K_A|$ and $|L_A|$ and whose squared fidelity is at least
\begin{align}
 F(\omega,\zeta).
 \label{eq:controlled-Uhlmann-conclusion}
\end{align}
The conclusion remains valid when the physical output of $\mathcal{A}$ is isometrically embedded into a larger declared output space $L_A$.
\end{lemma}

\begin{proof}
	Let $N=|J|$ and write the block-diagonal states as
	\begin{align}
		\omega=\sum_{j=1}^N\ket{j}\!\bra{j}\otimes\omega_{L_AR^n}^j,
		\qquad
		\zeta=\sum_{j=1}^N\ket{j}\!\bra{j}\otimes
		\frac{1}{N}\pi_{L_A}\otimes\psi_R^{\otimes n}.
		\label{eq:controlled-Uhlmann-blocks}
	\end{align}
	Set
	\begin{align}
		f_j:=\norm{\sqrt{\omega^j}
			\sqrt{N^{-1}\pi_{L_A}\otimes\psi_R^{\otimes n}}}_1.
		\label{eq:branch-fidelity}
	\end{align}
	Block diagonality gives
	\begin{align}
		\sqrt{F(\omega,\zeta)}=\sum_{j=1}^Nf_j.
		\label{eq:block-fidelity-sum}
	\end{align}
	Because outcome $j$ is represented by a single Kraus operator, the corresponding subnormalized global post-measurement vector purifies $\omega^j$, and its complementary system is held by Bob.  Uhlmann's theorem~\cite{uhlmann1976transition} therefore provides an isometry on Bob's system whose overlap with
	$N^{-1/2}\Phi_{L_AL_B}\otimes\psi_{\widehat A BR}^{\otimes n}$ is $f_j$.  The branch target has squared norm $1/N$, so the overlap with the corresponding normalized ideal branch is $\sqrt{N}f_j$; summing the squared branch overlaps produces the factor $N$ below.  After the outcome register and decoder environments are discarded, the fidelity with the pure ideal target is at least
	\begin{align}
		N\sum_{j=1}^Nf_j^2
		\geq\left(\sum_{j=1}^Nf_j\right)^2
		=F(\omega,\zeta),
		\label{eq:controlled-Uhlmann-proof}
	\end{align}
	where the inequality follows from the Cauchy--Schwarz inequality.
\end{proof}

\subsection{Double pinching}

The construction in this subsection adapts the double-pinching method of Rubboli and Tomamichel~\cite{rubboli2026strong}, itself embedded in the Log-Euclidean strong-converse strategy of Mosonyi and Ogawa~\cite{mosonyi2017strong}.  The new point required here is to preserve the quantum marginal relevant to state merging while simultaneously commuting the joint state, its marginal, and the auxiliary universal state.

Restrict $R$ to $\supp(\rho_R)$ and write $d_R:=|R|$.  For each block size $m$, let $\omega_{R^m}$ be the universal state in Proposition~\ref{prop:universal-state}, and define
\begin{align}
 \widetilde\rho_{A^mR^m}^{(m)}
 :=\left(\mathrm{id}_{A^m}\otimes
 \P_{\rho_R^{\otimes m}}\circ\P_{\omega_{R^m}}\right)
 (\rho_{AR}^{\otimes m}).
 \label{eq:double-pinched-state}
\end{align}
The state $\widetilde\rho^{(m)}$ is invariant under simultaneous permutations of the $m$ copies.  Since $\omega_{R^m}$ commutes with $\rho_R^{\otimes m}$, their spectral projections commute, and therefore the pinching maps $\P_{\omega_{R^m}}$ and $\P_{\rho_R^{\otimes m}}$ commute.  Consequently,
\begin{align}
 \widetilde\rho_{R^m}^{(m)}=\rho_R^{\otimes m},
 \label{eq:double-pinched-marginal}
\end{align}
and the three operators
\begin{align}
 \widetilde\rho_{A^mR^m}^{(m)},
 \qquad I_{A^m}\otimes\rho_R^{\otimes m},
 \qquad I_{A^m}\otimes\omega_{R^m}
 \label{eq:three-commuting-operators}
\end{align}
commute pairwise.

\begin{lemma}[Log-Euclidean-to-club-sandwiched comparison]
\label{lem:double-pinching-entropy}
Let $\alpha\in[1/2,1)$ and
$\frac{1-2\alpha}{1-\alpha}\leq\lambda\leq0$.  Then
\begin{align}
 H_{\alpha,\infty}^{\lambda}(A^m|R^m)_{\widetilde\rho^{(m)}}
 \geq
 m\widetilde H_\alpha^\lambda(A|R)_\rho
 +\lambda(d_R^2-1)\log(m+1).
 \label{eq:double-pinching-entropy}
\end{align}
\end{lemma}

\begin{proof}
By Proposition~\ref{prop:universal-state}, an optimizer $\sigma_{R^m}^\star$ in the Log-Euclidean conditional entropy can be chosen permutation-invariant and hence satisfies
\begin{align}
